INSERT INTO public.topics (id, title, slug, usmle_step, "order", section, is_free_demo, mcq_count, case_count)
INSERT INTO public.mcqs (topic_id, question, options, correct_index, explanation, difficulty, "order", type) VALUES
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 24-year-old man presents with 3 weeks of polyuria, polydipsia, and a 6-kg unintentional weight loss. He reports fatigue and blurred vision. His BMI is 21 kg/m2. Laboratory studies show a random glucose of 342 mg/dL, HbA1c of 11.2%, and positive anti-GAD antibodies. Ketones are absent in the urine. Which of the following is the most likely diagnosis?', '["Type 2 diabetes mellitus", "Type 1 diabetes mellitus", "Secondary diabetes from chronic pancreatitis", "Maturity-onset diabetes of the young (MODY)", "Latent autoimmune diabetes in adults (LADA)"]'::jsonb, 1, 'This patient has type 1 diabetes mellitus: young age, lean body habitus, rapid weight loss, and positive anti-GAD antibodies indicate autoimmune destruction of pancreatic beta cells. Type 2 diabetes typically presents in older, overweight patients with insulin resistance and gradual onset, and autoantibodies are absent. Secondary diabetes from chronic pancreatitis requires a history of pancreatitis with exocrine insufficiency and imaging findings. MODY presents with a strong autosomal dominant family history, mild hyperglycemia, and negative autoantibodies. LADA is autoimmune diabetes diagnosed after age 30 with a slower progression to insulin dependence, making it unlikely in this 24-year-old with classic acute symptoms.', 'Easy', 1, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 52-year-old woman with a BMI of 33 kg/m2 is found to have a fasting glucose of 128 mg/dL on routine screening. A repeat fasting glucose is 131 mg/dL, and her HbA1c is 6.6%. She has no symptoms of hyperglycemia. Which of the following is the most appropriate next step?', '["Repeat HbA1c in 3 months without treatment", "Order a 2-hour oral glucose tolerance test to confirm", "Diagnose diabetes and start metformin", "Diagnose prediabetes and recommend lifestyle modification only", "Start insulin therapy"]'::jsonb, 2, 'Diabetes is diagnosed when fasting glucose is ≥126 mg/dL on two separate occasions, and this patient meets criteria on two measurements, so diabetes should be diagnosed and treatment started. A repeat HbA1c is unnecessary since the diagnosis is already established by two fasting values. An oral glucose tolerance test is not needed when fasting glucose confirms the diagnosis. Prediabetes is defined by fasting glucose 100–125 mg/dL or HbA1c 5.7–6.4%, both below her values. Insulin is not first-line for asymptomatic type 2 diabetes; metformin is the preferred initial agent in a patient with adequate renal function.', 'Medium', 2, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 38-year-old man has a fasting glucose of 112 mg/dL and an HbA1c of 6.0% on screening. He is overweight with a BMI of 29 kg/m2 and has a father with type 2 diabetes. He asks what these results mean. Which of the following is the most appropriate interpretation and next step?', '["Normal glucose tolerance; repeat screening in 3 years", "Prediabetes; start metformin immediately", "Diabetes; begin insulin therapy", "Prediabetes; intensive lifestyle modification and recheck in 3–6 months", "Impaired glucose tolerance; order a random glucose to confirm diabetes"]'::jsonb, 3, 'Fasting glucose 100–125 mg/dL and HbA1c 5.7–6.4% define prediabetes, so this patient has prediabetes and needs intensive lifestyle modification with weight loss, dietary changes, and exercise, with retesting in 3–6 months. Normal glucose tolerance requires fasting glucose <100 mg/dL and HbA1c <5.7%, which he does not meet. Metformin is considered for prediabetes mainly in patients younger than 60 with BMI ≥35, prior gestational diabetes, or rising A1c, none of which apply here. He does not meet diabetes criteria (fasting glucose ≥126 or HbA1c ≥6.5%), so insulin is inappropriate. A random glucose does not diagnose diabetes and adds nothing when fasting values already establish prediabetes.', 'Medium', 3, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 58-year-old man with type 2 diabetes and heart failure with reduced ejection fraction (EF 30%) is on metformin 1000 mg twice daily. His HbA1c is 8.1%, eGFR is 62 mL/min/1.73 m2, and he has no contraindications to additional therapy. Which of the following is the most appropriate next step in his management?', '["Add a sulfonylurea such as glipizide", "Add basal insulin glargine", "Add an SGLT2 inhibitor such as empagliflozin", "Add a thiazolidinedione such as pioglitazone", "Increase metformin to the maximum dose"]'::jsonb, 2, 'An SGLT2 inhibitor is the most appropriate add-on because it lowers glucose and independently reduces heart failure hospitalizations and cardiovascular death in patients with heart failure with reduced ejection fraction, regardless of diabetes status. A sulfonylurea lowers glucose but causes weight gain and hypoglycemia without cardiovascular benefit. Basal insulin lowers glucose effectively but does not improve heart failure outcomes and adds hypoglycemia risk and weight gain. A thiazolidinedione is contraindicated in heart failure because it causes fluid retention and worsens symptoms. Increasing metformin further is unlikely to reach the A1c target and does not address the heart failure benefit this patient needs.', 'Hard', 4, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 64-year-old woman with type 2 diabetes, obesity (BMI 38 kg/m2), and established atherosclerotic cardiovascular disease has an HbA1c of 8.4% on metformin. Her eGFR is 55 mL/min/1.73 m2. She wants a medication that helps with weight loss and heart protection. Which of the following is the most appropriate next step?', '["Add a DPP-4 inhibitor such as sitagliptin", "Add a sulfonylurea such as glyburide", "Add a GLP-1 receptor agonist such as semaglutide", "Add basal insulin", "Add a meglitinide such as repaglinide"]'::jsonb, 2, 'A GLP-1 receptor agonist such as semaglutide is the best choice because it improves glycemic control, produces substantial weight loss, and reduces major adverse cardiovascular events in patients with type 2 diabetes and established cardiovascular disease. A DPP-4 inhibitor is weight-neutral and lowers A1c modestly but has no proven cardiovascular outcome benefit. A sulfonylurea causes weight gain and hypoglycemia and offers no cardiovascular protection. Basal insulin lowers glucose but causes weight gain and hypoglycemia without cardiovascular benefit. A meglitinide is a short-acting secretagogue useful for postprandial control but causes hypoglycemia and weight gain without cardiovascular benefit.', 'Medium', 5, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 71-year-old man with long-standing type 2 diabetes on metformin and glipizide has an HbA1c of 9.2%. He has chronic kidney disease with an eGFR of 28 mL/min/1.73 m2. His fasting glucose is 210 mg/dL and postprandial glucose is 280 mg/dL. Which of the following is the most appropriate next step in his management?', '["Continue current therapy and add an SGLT2 inhibitor", "Add a thiazolidinedione", "Stop metformin and glipizide and start basal-bolus insulin", "Add a DPP-4 inhibitor at full dose", "Increase glipizide to the maximum dose"]'::jsonb, 2, 'Metformin is contraindicated when eGFR falls below 30 mL/min/1.73 m2 because of lactic acidosis risk, and sulfonylureas carry a high hypoglycemia risk in advanced kidney disease, so both should be stopped and insulin started, since insulin is cleared independently of renal function and is safe in CKD. An SGLT2 inhibitor is inappropriate to add now because it is contraindicated for glycemic control at eGFR below 30 and does not address his severe hyperglycemia. A thiazolidinedione is risky in CKD with fluid retention and offers no advantage here. A DPP-4 inhibitor requires dose reduction in severe CKD and would not lower his A1c from 9.2% adequately. Increasing glipizide worsens hypoglycemia risk without solving the metformin contraindication.', 'Hard', 6, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 19-year-old woman with type 1 diabetes for 6 years uses a basal-bolus insulin regimen. She develops a viral gastroenteritis with vomiting and is unable to eat. Her glucose is 180 mg/dL and urine ketones are trace. She asks whether she should stop her insulin. Which of the following is the most appropriate advice?', '["Stop all insulin until she can eat again", "Stop basal insulin but continue prandial insulin", "Continue basal insulin, hold prandial insulin, check glucose and ketones frequently, and stay hydrated", "Switch to a sulfonylurea until the illness resolves", "Double her basal insulin dose to prevent ketoacidosis"]'::jsonb, 2, 'During illness, basal insulin must never be stopped in type 1 diabetes because the body still needs insulin to suppress ketogenesis; stopping it precipitates diabetic ketoacidosis even with normal glucose. Prandial insulin can be held while she is not eating, with frequent glucose and ketone monitoring and hydration to detect evolving ketoacidosis early. Stopping all insulin is dangerous and is the classic precipitant of DKA during intercurrent illness. A sulfonylurea is ineffective in type 1 diabetes because there is no endogenous insulin to stimulate. Doubling basal insulin without eating risks severe hypoglycemia; doses are adjusted based on glucose and ketone trends, not doubled blindly.', 'Medium', 7, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 16-year-old boy with newly diagnosed type 1 diabetes is started on basal-bolus insulin. His parents ask about the best regimen to mimic normal physiology and reduce hypoglycemia. Which of the following is the most appropriate initial regimen?', '["NPH insulin twice daily alone", "Regular insulin before meals only", "Premixed 70/30 insulin twice daily", "Long-acting basal insulin once daily plus rapid-acting insulin before each meal", "Sliding-scale regular insulin without basal coverage"]'::jsonb, 3, 'A basal-bolus regimen with long-acting basal insulin once daily plus rapid-acting insulin before each meal best mimics physiologic insulin secretion, providing steady background insulin and meal coverage, and is the standard of care for type 1 diabetes. NPH insulin alone has a pronounced peak that increases hypoglycemia risk and does not provide adequate meal coverage. Premixed 70/30 insulin is inflexible, forces fixed meal timing and carbohydrate intake, and increases hypoglycemia risk. Regular insulin before meals only leaves the patient without basal coverage overnight, risking fasting hyperglycemia and ketosis. Sliding-scale regular insulin without basal insulin is outdated and dangerous because it treats hyperglycemia reactively while allowing ketogenesis between doses.', 'Easy', 8, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 27-year-old man with type 1 diabetes wakes up sweaty, shaky, and confused at 3 a.m. His glucose is 48 mg/dL. He is alert enough to swallow. Which of the following is the most appropriate immediate management?', '["Give a complex carbohydrate snack and go back to sleep", "Inject glucagon intramuscularly", "Give a glass of milk and recheck in 1 hour", "Administer intravenous dextrose immediately", "Give 15 g of fast-acting carbohydrate, recheck in 15 minutes, and repeat if still low"]'::jsonb, 4, 'The 15-15 rule is the correct treatment for hypoglycemia in a conscious patient who can swallow: 15 g of fast-acting carbohydrate, recheck glucose in 15 minutes, and repeat until glucose is above 70 mg/dL, followed by a small snack if the next meal is more than an hour away. Glucagon is reserved for severe hypoglycemia when the patient cannot swallow or is unconscious. Milk contains lactose and protein that slow glucose absorption, making it a poor choice for rapid correction, and waiting an hour is unsafe. Intravenous dextrose is used in the hospital for severe hypoglycemia or when the patient cannot take oral glucose. A complex carbohydrate snack alone absorbs too slowly to correct an acute low and risks prolonged neuroglycopenia.', 'Easy', 9, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 22-year-old woman with type 1 diabetes for 8 years presents with 2 days of nausea, vomiting, abdominal pain, and rapid breathing. She ran out of insulin 3 days ago. Her glucose is 520 mg/dL, pH 7.18, bicarbonate 10 mEq/L, anion gap 26, potassium 5.2 mEq/L, and urine ketones are large. Which of the following is the most likely diagnosis?', '["Hyperosmolar hyperglycemic state", "Alcoholic ketoacidosis", "Lactic acidosis", "Diabetic ketoacidosis", "Starvation ketosis"]'::jsonb, 3, 'This is diabetic ketoacidosis: hyperglycemia with an anion gap metabolic acidosis, low bicarbonate, acidemic pH, and large ketones in a patient with type 1 diabetes who stopped insulin. Hyperosmolar hyperglycemic state features much higher glucose (often >600 mg/dL) and severe hyperosmolality without significant ketosis or acidosis. Lactic acidosis causes an anion gap acidosis but without hyperglycemia and ketones of this magnitude. Alcoholic ketoacidosis occurs in chronic alcohol use with poor intake and typically normal or low glucose. Starvation ketosis produces only mild ketosis with normal glucose and near-normal pH, not this degree of acidosis.', 'Easy', 10, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 30-year-old man with diabetic ketoacidosis is being treated with intravenous fluids and an insulin infusion. His initial potassium was 5.6 mEq/L. After 4 hours, his glucose is 250 mg/dL, potassium is 3.1 mEq/L, and bicarbonate is 16 mEq/L. Which of the following is the most appropriate next step?', '["Stop the insulin infusion because glucose is below 300 mg/dL", "Switch to subcutaneous insulin immediately", "Give a bolus of sodium bicarbonate", "Continue insulin infusion, add dextrose to fluids, and replace potassium", "Stop potassium replacement because the anion gap is closing"]'::jsonb, 3, 'The insulin infusion must continue until the anion gap closes, even though glucose has fallen below 250 mg/dL; dextrose is added to the intravenous fluids to allow continued insulin without hypoglycemia, and potassium must be replaced because insulin drives potassium intracellularly and the level has fallen to 3.1 mEq/L. Stopping insulin prematurely allows ketogenesis to resume and the acidosis to recur. Sodium bicarbonate is not routinely given in DKA and is reserved for severe acidemia with pH below 6.9. Switching to subcutaneous insulin is appropriate only after the anion gap has closed and the patient can eat. Potassium replacement remains essential while insulin continues, since total body potassium is depleted despite the initially normal serum level.', 'Hard', 11, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 45-year-old man with type 1 diabetes presents with vomiting, abdominal pain, and Kussmaul respirations. Labs show glucose 480 mg/dL, sodium 132 mEq/L, potassium 5.8 mEq/L, bicarbonate 12 mEq/L, and pH 7.22. Which of the following is the most appropriate initial management?', '["Give an insulin bolus followed by subcutaneous insulin", "Give potassium chloride before starting fluids", "Administer sodium bicarbonate immediately", "Start isotonic saline, check potassium, and begin a fixed-rate insulin infusion", "Start a dextrose infusion to lower the glucose gradually"]'::jsonb, 3, 'Initial DKA management is aggressive isotonic saline resuscitation to restore perfusion, followed by a fixed-rate insulin infusion once potassium is confirmed to be above 3.3 mEq/L; this patient has potassium of 5.8 mEq/L, so insulin can start after fluids begin. An insulin bolus followed by subcutaneous insulin is not the standard approach; a continuous infusion is preferred. Sodium bicarbonate is not indicated unless pH is below 6.9. Potassium should not be given before fluids and insulin when the level is already elevated, and hypokalemia must be corrected before starting insulin only when potassium is below 3.3 mEq/L. A dextrose infusion is added later when glucose falls below 250 mg/dL to permit continued insulin infusion.', 'Medium', 12, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'An 82-year-old man with type 2 diabetes is brought to the emergency department with confusion and severe dehydration after 5 days of decreased oral intake and a urinary tract infection. His glucose is 920 mg/dL, sodium 150 mEq/L, calculated osmolality 335 mOsm/kg, bicarbonate 24 mEq/L, pH 7.38, and ketones are trace. Which of the following is the most likely diagnosis?', '["Diabetic ketoacidosis", "Hyperglycemic hyperosmolar nonketotic coma due to stroke", "Lactic acidosis", "Hyperosmolar hyperglycemic state", "Starvation ketosis"]'::jsonb, 3, 'This is hyperosmolar hyperglycemic state: marked hyperglycemia above 600 mg/dL with severe hyperosmolality above 320 mOsm/kg, minimal ketosis, and normal pH and bicarbonate in an elderly patient with type 2 diabetes precipitated by infection and dehydration. Diabetic ketoacidosis requires significant ketosis with an anion gap acidosis and low bicarbonate, which are absent here. Lactic acidosis causes an anion gap acidosis without this degree of hyperglycemia or hyperosmolality. A stroke does not explain the extreme glucose and osmolality, and altered mental status here is from hyperosmolality. Starvation ketosis produces mild ketosis with normal glucose, not glucose of 920 mg/dL.', 'Medium', 13, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 76-year-old woman with hyperosmolar hyperglycemic state has a glucose of 880 mg/dL, sodium 148 mEq/L, and calculated osmolality 330 mOsm/kg. She is hypotensive and severely dehydrated. Which of the following is the most appropriate initial management?', '["Start an insulin infusion at a high fixed rate immediately", "Start subcutaneous basal insulin and oral fluids", "Administer sodium bicarbonate to correct the osmolality", "Give a bolus of 50% dextrose to prevent hypoglycemia", "Give aggressive isotonic saline resuscitation first, then start insulin"]'::jsonb, 4, 'In hyperosmolar hyperglycemic state, aggressive isotonic saline resuscitation comes first to restore intravascular volume and perfusion; insulin is started only after initial fluid resuscitation because insulin without fluids can cause a precipitous fall in osmolality and vascular collapse. Starting a high-rate insulin infusion immediately risks rapid osmotic shifts and cerebral edema. Sodium bicarbonate does not correct hyperosmolality and is not indicated with a normal pH. A dextrose bolus would worsen hyperglycemia and hyperosmolality. Subcutaneous insulin and oral fluids are inadequate for a hypotensive, severely dehydrated patient who needs intravenous resuscitation and close monitoring.', 'Medium', 14, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 68-year-old man with type 2 diabetes on insulin is found confused and diaphoretic by his wife. His glucose is 42 mg/dL. He is drowsy but can swallow. After treatment with oral glucose, his glucose rises to 95 mg/dL. Which of the following is the most appropriate next step to prevent recurrent hypoglycemia overnight?', '["Give a long-acting carbohydrate snack and review his insulin regimen", "Administer glucagon intramuscularly", "Start an intravenous dextrose infusion", "Give another dose of fast-acting carbohydrate immediately", "Discontinue all insulin permanently"]'::jsonb, 0, 'After correcting acute hypoglycemia with fast-acting carbohydrate, a long-acting carbohydrate snack (or a small meal if within an hour) helps sustain glucose overnight, and the insulin regimen should be reviewed for excessive dosing, missed meals, or renal impairment. Glucagon is used for severe hypoglycemia when the patient cannot swallow, which is not the case here. An intravenous dextrose infusion is reserved for refractory or severe hypoglycemia in hospital, not after successful oral correction. Another dose of fast-acting carbohydrate immediately is unnecessary once glucose is above 70 mg/dL and risks rebound hyperglycemia. Discontinuing insulin permanently is inappropriate; the dose should be adjusted, not stopped.', 'Medium', 15, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 55-year-old man with type 2 diabetes on glipizide presents with recurrent episodes of sweating, tremor, and confusion that resolve after eating. He drinks alcohol regularly and often skips meals. His fasting glucose is 55 mg/dL during an episode. Which of the following is the most likely cause of his hypoglycemia?', '["Insulinoma", "Factitious insulin administration", "Adrenal insufficiency", "Reactive hypoglycemia after meals", "Sulfonylurea use combined with alcohol and missed meals"]'::jsonb, 4, 'Sulfonylureas stimulate insulin secretion independent of glucose, and alcohol impairs hepatic gluconeogenesis while missed meals remove the glucose source, together causing hypoglycemia in this patient on glipizide. An insulinoma causes fasting hypoglycemia but would not be explained by his medication and alcohol history, and it typically presents with inappropriately high insulin and C-peptide levels during a supervised fast. Adrenal insufficiency causes hypoglycemia with hypotension, hyponatremia, and hyperkalemia, which are not described here. Reactive hypoglycemia occurs 2–4 hours after meals, not fasting. Factitious insulin administration produces low C-peptide with high insulin levels and requires a psychiatric or access history that is absent.', 'Medium', 16, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 47-year-old woman with type 1 diabetes is found unconscious at home by her husband. Her glucose is 32 mg/dL and she cannot swallow. Which of the following is the most appropriate immediate management?', '["Give oral glucose gel between her cheek and gum", "Wait for her to wake up on her own", "Give a glass of orange juice", "Administer subcutaneous insulin to stimulate counter-regulation", "Administer glucagon 1 mg intramuscularly and call emergency services"]'::jsonb, 4, 'Severe hypoglycemia with unconsciousness requires glucagon 1 mg intramuscularly, which stimulates hepatic glycogenolysis, along with calling emergency services; oral intake is unsafe in an unconscious patient because of aspiration risk. Oral glucose gel is not recommended in an unconscious patient since it can be aspirated and is unreliable. Orange juice cannot be swallowed safely while unconscious. Insulin would worsen hypoglycemia and is never given to treat a low glucose. Waiting risks prolonged neuroglycopenia, seizures, and brain injury, so immediate glucagon and emergency care are essential.', 'Easy', 17, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 60-year-old man with type 2 diabetes for 12 years has an HbA1c of 7.8%. He reports foamy urine and his urine albumin-to-creatinine ratio is 320 mg/g with an eGFR of 58 mL/min/1.73 m2. His blood pressure is 142/88 mm Hg. Which of the following is the most appropriate next step to slow progression of his kidney disease?', '["Start an ACE inhibitor and optimize blood pressure and glycemic control", "Start a calcium channel blocker alone", "Restrict dietary protein to less than 0.4 g/kg/day", "Start hemodialysis", "Discontinue metformin and start insulin only"]'::jsonb, 0, 'Diabetic nephropathy with macroalbuminuria requires an ACE inhibitor to reduce intraglomerular pressure and proteinuria, plus blood pressure control to below 130/80 mm Hg and glycemic optimization, which together slow CKD progression. A calcium channel blocker alone lowers blood pressure but does not reduce proteinuria as effectively as RAAS blockade. Severe protein restriction below 0.4 g/kg/day risks malnutrition and is not recommended; moderate restriction around 0.8 g/kg/day is advised. Hemodialysis is indicated only for end-stage kidney disease, not at eGFR 58. Stopping metformin is unnecessary at this eGFR, and insulin alone does not provide the renoprotective effect of RAAS blockade.', 'Medium', 18, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 55-year-old woman with type 2 diabetes for 10 years has no visual symptoms. Her last eye examination was 4 years ago. Which of the following is the most appropriate screening recommendation for diabetic retinopathy?', '["Annual dilated eye examination starting now", "Eye examination only if she develops visual symptoms", "Dilated eye examination every 5 years", "Optical coherence tomography annually instead of a dilated examination", "No screening is needed because she has no symptoms"]'::jsonb, 0, 'Patients with type 2 diabetes should have a comprehensive dilated eye examination at diagnosis and annually thereafter, because diabetic retinopathy is often asymptomatic until advanced, and early detection allows laser therapy or anti-VEGF treatment to prevent vision loss. Waiting for visual symptoms misses the window for effective intervention, since symptoms appear only with macular edema or proliferative disease. A 5-year interval is too long and risks missing progressive retinopathy. Optical coherence tomography is an adjunct for macular edema but does not replace a dilated retinal examination. No screening is dangerous because retinopathy is the leading cause of blindness in working-age adults with diabetes.', 'Easy', 19, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 62-year-old man with type 2 diabetes for 15 years reports burning pain and numbness in both feet in a stocking distribution, worse at night. Examination shows decreased vibration sense and absent ankle reflexes. Which of the following is the most appropriate management for his neuropathic pain?', '["Start a tricyclic antidepressant such as amitriptyline or duloxetine", "Start a nonsteroidal anti-inflammatory drug", "Start an opioid such as oxycodone", "Start a topical capsaicin cream as first-line therapy", "Reassure him that the pain will resolve with tighter glucose control alone"]'::jsonb, 0, 'Diabetic peripheral neuropathy with painful symptoms is treated first-line with a tricyclic antidepressant such as amitriptyline, an SNRI such as duloxetine, or gabapentinoids, which modulate pain signaling. NSAIDs are ineffective for neuropathic pain and carry renal and cardiovascular risks in diabetes. Opioids are not first-line because of limited efficacy, tolerance, and addiction risk. Topical capsaicin can help localized pain but is not first-line for diffuse stocking-distribution neuropathy. Tighter glucose control slows progression of neuropathy but does not relieve established pain, so symptomatic treatment is needed alongside glycemic optimization.', 'Medium', 20, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 66-year-old man with type 2 diabetes for 18 years has a nonhealing ulcer on the plantar surface of his right foot. He has diminished pedal pulses and loss of protective sensation. Which of the following is the most appropriate next step in his management?', '["Apply a topical antibiotic and continue walking normally", "Apply a heating pad to improve circulation", "Amputate the foot immediately", "Start oral antibiotics and discharge without follow-up", "Offload the foot, assess vascular status with ankle-brachial index, and obtain wound cultures"]'::jsonb, 4, 'A diabetic foot ulcer requires offloading to remove pressure from the wound, vascular assessment with an ankle-brachial index to detect peripheral arterial disease, and wound cultures to guide antibiotics, along with debridement and glycemic control. Topical antibiotics alone and continued walking worsen the ulcer and risk infection and amputation. Immediate amputation is reserved for life-threatening infection or unsalvageable tissue, not an uncomplicated ulcer. Oral antibiotics without offloading, vascular assessment, or follow-up are inadequate and miss the underlying ischemia and neuropathy. A heating pad is dangerous in a patient with loss of protective sensation because it can cause burns without the patient noticing.', 'Medium', 21, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 59-year-old man with type 2 diabetes, hypertension, and hyperlipidemia has an HbA1c of 7.5%. He smokes one pack per day. His LDL cholesterol is 110 mg/dL on no statin. Which of the following is the most appropriate intervention to reduce his cardiovascular risk?', '["Start a high-intensity statin and counsel smoking cessation", "Start a low-dose aspirin alone", "Increase his diabetes medication to lower HbA1c below 6.0%", "Start a beta-blocker for cardioprotection", "No additional therapy is needed because his HbA1c is at goal"]'::jsonb, 0, 'Patients with diabetes aged 40–75 with additional cardiovascular risk factors should receive a high-intensity statin regardless of baseline LDL, and smoking cessation is the single most effective intervention to reduce cardiovascular events. Aspirin alone is insufficient and is no longer routinely recommended for primary prevention in diabetes. Lowering HbA1c below 6.0% in an older patient with long-standing diabetes increases hypoglycemia risk without cardiovascular benefit; a target of less than 7.0–7.5% is appropriate. A beta-blocker is not indicated for primary prevention without a specific indication such as prior myocardial infarction or heart failure. His HbA1c is near goal, but his cardiovascular risk remains high from smoking and untreated hyperlipidemia.', 'Hard', 22, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 70-year-old woman with type 2 diabetes and peripheral arterial disease has intermittent claudication after walking two blocks. Her ankle-brachial index is 0.65. She is on a statin and aspirin. Which of the following is the most appropriate next step in her management?', '["Start cilostazol and a supervised exercise program", "Proceed directly to surgical bypass", "Stop the statin because it causes muscle pain", "Start a beta-blocker to reduce cardiac demand", "Recommend bed rest to avoid claudication"]'::jsonb, 0, 'Intermittent claudication is managed first with a supervised exercise program, which improves walking distance, and cilostazol, a phosphodiesterase inhibitor that increases walking distance in peripheral arterial disease. Surgical bypass is reserved for critical limb ischemia or lifestyle-limiting claudication refractory to conservative therapy. Stopping the statin removes important cardiovascular protection and is not indicated without true intolerance. A beta-blocker is not a treatment for claudication and is not contraindicated in peripheral arterial disease, but it does not improve walking distance. Bed rest worsens deconditioning and claudication; exercise is the cornerstone of therapy.', 'Medium', 23, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 29-year-old woman at 26 weeks of gestation is screened with a 1-hour 50-g oral glucose challenge test, which shows a glucose of 158 mg/dL. Which of the following is the most appropriate next step?', '["Diagnose gestational diabetes and start insulin immediately", "Perform a 3-hour 100-g oral glucose tolerance test", "Reassure her that the result is normal", "Start metformin", "Order a fasting glucose to confirm the diagnosis"]'::jsonb, 1, 'A 1-hour glucose challenge result of 140 mg/dL or higher is abnormal and requires a diagnostic 3-hour 100-g oral glucose tolerance test; gestational diabetes is diagnosed if two or more values meet or exceed the Carpenter-Coustan thresholds. A single abnormal screening value does not by itself establish the diagnosis or justify immediate insulin. The result is not normal, since the threshold is 140 mg/dL, so reassurance is inappropriate. Metformin is not first-line for gestational diabetes; dietary management is initial therapy, with insulin added if targets are not met. A fasting glucose alone does not diagnose gestational diabetes under the two-step screening approach.', 'Medium', 24, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 32-year-old woman with gestational diabetes diagnosed at 28 weeks has fasting glucose of 105 mg/dL and 2-hour postprandial glucose of 145 mg/dL despite 2 weeks of dietary modification and exercise. Which of the following is the most appropriate next step?', '["Continue dietary management alone", "Start insulin therapy", "Start metformin as first-line therapy", "Start a sulfonylurea", "Start a GLP-1 receptor agonist"]'::jsonb, 1, 'When gestational diabetes is not controlled with diet and exercise, insulin is the preferred pharmacologic therapy because it does not cross the placenta and has the strongest safety record for the fetus. Continuing diet alone is inadequate since her fasting glucose exceeds the target of 95 mg/dL and postprandial glucose exceeds 120 mg/dL. Metformin crosses the placenta and, while used in some settings, is not the preferred first-line agent in the United States. Sulfonylureas such as glyburide cross the placenta and are associated with neonatal hypoglycemia. GLP-1 receptor agonists are not recommended in pregnancy because of insufficient safety data.', 'Hard', 25, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 35-year-old woman had gestational diabetes during her pregnancy, which resolved after delivery. She asks about her long-term risk and follow-up. Which of the following is the most appropriate recommendation?', '["No further screening is needed since the diabetes resolved", "Screen with a 75-g oral glucose tolerance test at 4–12 weeks postpartum, then lifelong screening every 1–3 years", "Start metformin immediately to prevent type 2 diabetes", "Screen with HbA1c once at 1 year postpartum only", "Resume screening only if she becomes pregnant again"]'::jsonb, 1, 'Women with gestational diabetes should be screened with a 75-g oral glucose tolerance test at 4–12 weeks postpartum, then screened lifelong every 1–3 years, because they have a markedly increased risk of developing type 2 diabetes. No further screening is unsafe since up to half develop type 2 diabetes within 5–10 years. Metformin is not started automatically after delivery; lifestyle modification is recommended, with metformin considered for those with prediabetes and additional risk factors. A single HbA1c at 1 year is insufficient because the postpartum OGTT detects persistent diabetes earlier and ongoing screening is needed. Waiting until the next pregnancy misses years of undiagnosed diabetes and its complications.', 'Medium', 26, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 22-year-old man has mild fasting hyperglycemia (glucose 130 mg/dL) discovered on routine labs. He is lean with a BMI of 22 kg/m2, has no ketosis, and his mother and maternal grandfather were diagnosed with diabetes in their 20s. Autoantibodies are negative and his C-peptide is normal. Which of the following is the most likely diagnosis?', '["Type 1 diabetes mellitus", "Type 2 diabetes mellitus", "Maturity-onset diabetes of the young (MODY)", "Secondary diabetes from Cushing syndrome", "Latent autoimmune diabetes in adults (LADA)"]'::jsonb, 2, 'MODY is suggested by early-onset diabetes in a lean young person with a strong autosomal dominant family history across three generations, negative autoantibodies, preserved C-peptide, and mild hyperglycemia without ketosis. Type 1 diabetes presents with positive autoantibodies, low C-peptide, and often ketosis or weight loss. Type 2 diabetes typically occurs in overweight patients with insulin resistance and lacks this multigenerational early-onset pattern. Cushing syndrome causes secondary diabetes with central obesity, hypertension, and other stigmata of hypercortisolism that are absent here. LADA is autoimmune diabetes with positive autoantibodies and onset after age 30, which does not fit this patient.', 'Hard', 27, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 48-year-old man with chronic alcohol use presents with recurrent epigastric pain, steatorrhea, and new hyperglycemia with glucose of 260 mg/dL. CT shows a calcified pancreas with ductal dilation. Which of the following is the most likely cause of his diabetes?', '["Type 2 diabetes mellitus", "Type 3c diabetes from chronic pancreatitis", "Type 1 diabetes mellitus", "MODY", "Steroid-induced diabetes"]'::jsonb, 1, 'Type 3c diabetes results from chronic pancreatitis destroying both endocrine and exocrine pancreatic tissue; this patient has calcifications, ductal dilation, steatorrhea from exocrine insufficiency, and hyperglycemia from beta-cell loss. Type 2 diabetes is driven by insulin resistance and would not explain the steatorrhea or pancreatic calcifications. Type 1 diabetes is autoimmune with positive autoantibodies and typically presents in younger patients without chronic pancreatitis. MODY is a monogenic disorder with autosomal dominant inheritance and mild hyperglycemia, not pancreatic destruction. Steroid-induced diabetes requires glucocorticoid exposure, which is not described in this patient.', 'Medium', 28, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 41-year-old woman with Cushing disease on high-dose glucocorticoids develops hyperglycemia with fasting glucose 180 mg/dL and postprandial glucose 320 mg/dL. She has no prior history of diabetes. Which of the following is the most appropriate initial management?', '["Start metformin as first-line therapy", "Start basal-bolus insulin targeting postprandial hyperglycemia", "Start a sulfonylurea", "Start an SGLT2 inhibitor", "No treatment is needed until glucocorticoids are stopped"]'::jsonb, 1, 'Glucocorticoid-induced diabetes is characterized by marked postprandial hyperglycemia with relatively normal fasting glucose, and insulin, particularly with an emphasis on prandial coverage, is the most effective therapy because glucocorticoids cause severe insulin resistance. Metformin is inadequate for this degree of hyperglycemia and is often limited by acute illness or renal impairment. A sulfonylurea is less effective against steroid-induced insulin resistance and carries hypoglycemia risk. An SGLT2 inhibitor lowers glucose but is insufficient alone for glucose of 320 mg/dL and carries a risk of euglycemic ketoacidosis. Leaving hyperglycemia untreated risks infection, poor wound healing, and hyperglycemic crisis while steroids continue.', 'Hard', 29, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 74-year-old woman with type 2 diabetes is treated for hyperosmolar hyperglycemic state with intravenous isotonic saline and a low-dose insulin infusion. On admission her glucose was 810 mg/dL and calculated osmolality was 340 mOsm/kg. Over 6 hours her glucose falls to 420 mg/dL, but she develops worsening confusion and headache. Her current glucose is 420 mg/dL, sodium is 140 mEq/L, and potassium is 4.0 mEq/L. Which of the following is the most likely explanation for her deterioration?', '["Hypoglycemia from the insulin infusion", "Ischemic stroke from hyperviscosity", "Hypokalemia from insulin-driven potassium shifts", "Hypernatremia from hypotonic fluid losses", "Cerebral edema from an overly rapid fall in serum osmolality"]'::jsonb, 4, 'Cerebral edema is a known complication of overly rapid correction of hyperosmolality in hyperosmolar hyperglycemic state; as glucose falls quickly, water shifts into brain cells, causing headache, confusion, and deterioration, so osmolality should be lowered gradually and monitored. Hypoglycemia is not the cause because her glucose is 420 mg/dL, well above the hypoglycemic range. An ischemic stroke is possible in hyperviscosity but is less likely than cerebral edema as the explanation for deterioration during rapid osmotic correction. Hypokalemia is excluded because her potassium is normal at 4.0 mEq/L. Hypernatremia is not present because her sodium has fallen to 140 mEq/L, and worsening confusion with normal electrolytes points to osmotic brain injury.', 'Hard', 30, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 42-year-old woman presents with 6 months of fatigue, weight gain, cold intolerance, constipation, and dry skin. Examination shows a heart rate of 56/min, delayed deep tendon reflexes, and a diffusely enlarged, firm, nontender thyroid gland. Laboratory studies show TSH 18.4 mIU/L (normal 0.4-4.0) and free T4 0.5 ng/dL (normal 0.8-1.8). Anti-thyroid peroxidase antibodies are markedly elevated. What is the most likely diagnosis?', '["Pituitary adenoma causing secondary hypothyroidism", "Graves disease", "Hashimoto thyroiditis", "Subacute thyroiditis", "Toxic multinodular goiter"]'::jsonb, 0, 'Hashimoto thyroiditis is the most common cause of hypothyroidism in iodine-sufficient regions and presents with a firm, diffusely enlarged, nontender goiter, elevated TSH, low free T4, and positive anti-TPO antibodies. Graves disease causes hyperthyroidism with suppressed TSH and elevated T4, the opposite pattern. Subacute thyroiditis causes a painful, tender thyroid with a hyperthyroid phase. Toxic multinodular goiter causes hyperthyroidism, not hypothyroidism. Secondary hypothyroidism from a pituitary adenoma would show a low or inappropriately normal TSH with low free T4, not an elevated TSH.', 'Easy', 31, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 38-year-old woman is newly diagnosed with overt primary hypothyroidism due to Hashimoto thyroiditis. Her TSH is 12.6 mIU/L and free T4 is low. She weighs 70 kg and has no cardiac disease. She is started on levothyroxine. What is the most appropriate next step in management?', '["Defer treatment until she develops a goiter", "Start levothyroxine 25 mcg daily and recheck TSH in 2 weeks", "Start levothyroxine at approximately 1.6 mcg/kg/day and recheck TSH in 6 weeks", "Start levothyroxine 200 mcg daily and recheck TSH in 6 weeks", "Start liothyronine (T3) in addition to levothyroxine"]'::jsonb, 0, 'The standard full replacement dose of levothyroxine is approximately 1.6 mcg/kg/day, about 112 mcg daily for a 70-kg woman, with TSH rechecked in 6 weeks because steady state takes that long. A 25-mcg starting dose is too low for overt hypothyroidism in a young healthy patient and would leave her symptomatic. A 200-mcg dose is excessive and risks iatrogenic thyrotoxicosis. Combination T3 therapy is not first-line and offers no proven benefit over levothyroxine alone. Deferring treatment is inappropriate because overt hypothyroidism with a markedly elevated TSH and low T4 requires replacement.', 'Medium', 32, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 55-year-old woman has been taking levothyroxine 100 mcg daily for hypothyroidism for 2 years. Her TSH was previously normal but is now 9.8 mIU/L. She reports good adherence. She also recently started taking ferrous sulfate for iron deficiency anemia and calcium carbonate for osteoporosis, both taken at the same time as her levothyroxine in the morning. What is the most appropriate next step in management?', '["Switch to liothyronine", "Counsel her to take iron and calcium at least 4 hours apart from levothyroxine and recheck TSH in 6 weeks", "Discontinue levothyroxine and observe", "Order a thyroid ultrasound", "Increase levothyroxine to 150 mcg daily"]'::jsonb, 3, 'Iron and calcium supplements bind levothyroxine in the gut and impair its absorption when taken together, which explains the rising TSH despite adherence. Separating them by at least 4 hours restores absorption, and the TSH should be rechecked in 6 weeks before adjusting the dose. Increasing the dose without addressing absorption may overshoot once the interaction is corrected. Switching to liothyronine does not solve the absorption problem and is not first-line. Discontinuing levothyroxine would worsen hypothyroidism. A thyroid ultrasound is not indicated for a rising TSH in a patient with known Hashimoto thyroiditis.', 'Medium', 33, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 29-year-old woman presents with 3 months of palpitations, heat intolerance, tremor, weight loss despite increased appetite, and frequent stools. Examination shows a heart rate of 118/min, a fine tremor, warm moist skin, and a diffusely enlarged thyroid with a bruit. Laboratory studies show TSH <0.01 mIU/L, free T4 4.2 ng/dL, and positive thyroid-stimulating immunoglobulin (TSI). What is the most likely diagnosis?', '["Pituitary TSH-secreting adenoma", "Toxic multinodular goiter", "Graves disease", "Subacute thyroiditis", "Thyroid storm"]'::jsonb, 0, 'Graves disease is an autoimmune hyperthyroidism caused by TSI stimulating the TSH receptor, producing a diffuse goiter with a bruit, suppressed TSH, elevated T4, and positive TSI. Toxic multinodular goiter occurs in older patients with a nodular gland and negative TSI. Subacute thyroiditis causes a painful thyroid and is usually self-limited, without TSI. Thyroid storm is a life-threatening decompensation with fever, delirium, and organ dysfunction, not this subacute presentation. A TSH-secreting pituitary adenoma would show an elevated or inappropriately normal TSH, not a suppressed TSH.', 'Easy', 34, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 34-year-old woman is diagnosed with Graves disease. She has palpitations and a heart rate of 112/min but no heart failure, eye disease, or pregnancy. She prefers medical therapy. Which of the following is the most appropriate initial treatment?', '["High-dose levothyroxine", "Radioactive iodine ablation immediately", "Methimazole plus a beta-blocker for symptom control", "Total thyroidectomy", "Propylthiouracil as long-term therapy"]'::jsonb, 0, 'Methimazole is the preferred thionamide for Graves disease because it is more effective and has a better safety profile than propylthiouracil, and a beta-blocker such as propranolol provides rapid symptom control of palpitations and tremor. Radioactive iodine is an option but is usually not first-line in a young woman who prefers medical therapy, and it is contraindicated in pregnancy. Total thyroidectomy is reserved for large goiters, compressive symptoms, or failed medical therapy. Propylthiouracil is reserved for the first trimester of pregnancy or thyroid storm because of hepatotoxicity. Levothyroxine would worsen hyperthyroidism and is not a treatment for Graves disease.', 'Medium', 35, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 41-year-old woman with Graves disease has been treated with methimazole for 18 months. She now has bilateral proptosis, periorbital edema, diplopia on upward gaze, and a sensation of grittiness in her eyes. Her thyroid function is controlled. Which of the following is the most appropriate management of her eye disease?', '["Radioactive iodine ablation", "Refer to ophthalmology for Graves ophthalmopathy evaluation and consider glucocorticoids for active moderate-to-severe disease", "Start high-dose levothyroxine", "Reassure her that eye disease always resolves spontaneously", "Stop methimazole immediately"]'::jsonb, 3, 'Graves ophthalmopathy is an autoimmune inflammatory disease of the orbit that requires ophthalmology referral; active moderate-to-severe disease is treated with intravenous glucocorticoids, while mild disease is managed with lubrication and smoking cessation. Stopping methimazole does not treat the orbitopathy and would worsen hyperthyroidism. Radioactive iodine can worsen ophthalmopathy and is generally avoided in patients with active eye disease. Levothyroxine would worsen hyperthyroidism and does nothing for the orbit. Although mild ophthalmopathy may improve, moderate-to-severe disease does not reliably resolve spontaneously and can threaten vision.', 'Hard', 36, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 58-year-old woman with known Graves disease presents with fever of 39.8°C, confusion, agitation, heart rate of 148/min with atrial fibrillation, and vomiting. She recently stopped her methimazole. Laboratory studies show TSH <0.01 mIU/L and free T4 markedly elevated. Her Burch-Wartofsky score is 65. What is the most likely diagnosis?', '["Thyroid storm", "Pheochromocytoma", "Acute adrenal crisis", "Sepsis", "Myxedema coma"]'::jsonb, 4, 'Thyroid storm is a life-threatening decompensation of hyperthyroidism characterized by fever, altered mental status, tachycardia with atrial fibrillation, and gastrointestinal symptoms; a Burch-Wartofsky score above 45 is highly suggestive. Sepsis can cause fever and confusion but does not explain the markedly elevated free T4 and suppressed TSH with a known Graves history. Myxedema coma is the opposite state, with hypothermia, bradycardia, and hypoventilation. Pheochromocytoma causes episodic hypertension and palpitations but not fever with this thyroid profile. Adrenal crisis causes hypotension and hyponatremia, not hyperthermia with thyrotoxicosis.', 'Medium', 37, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 62-year-old man with untreated Graves disease is admitted to the intensive care unit with thyroid storm. He is febrile, tachycardic at 150/min, and confused. Which of the following is the most appropriate sequence of treatment?', '["Give a beta-blocker, supportive cooling and fluids, then propylthiouracil, followed by inorganic iodine after 1 hour, plus glucocorticoids", "Perform emergency total thyroidectomy immediately", "Give radioactive iodine as the first intervention", "Give levothyroxine first, then methimazole", "Give potassium iodide first, then propylthiouracil, then a beta-blocker"]'::jsonb, 4, 'Thyroid storm management requires supportive care with cooling and fluids plus a beta-blocker for tachycardia, a thionamide to block new hormone synthesis (propylthiouracil is preferred because it also blocks peripheral T4-to-T3 conversion), inorganic iodine given at least 1 hour after the thionamide to block hormone release, and glucocorticoids to reduce T4-to-T3 conversion and treat possible adrenal insufficiency. Giving levothyroxine would worsen thyrotoxicosis. Giving iodine before the thionamide can fuel new hormone synthesis. Emergency thyroidectomy is not first-line in an unstable patient. Radioactive iodine is too slow and is contraindicated in the acute setting.', 'Hard', 38, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 74-year-old woman is brought to the emergency department after being found unresponsive at home. She has a history of hypothyroidism and has not taken her levothyroxine for several weeks. Her temperature is 34.5°C, heart rate is 44/min, blood pressure is 88/56 mmHg, and respiratory rate is 8/min. She has periorbital edema, dry skin, and a delayed relaxation phase of deep tendon reflexes. Laboratory studies show TSH 68 mIU/L, free T4 undetectable, sodium 122 mEq/L, and glucose 58 mg/dL. What is the most likely diagnosis?', '["Septic shock", "Adrenal crisis", "Hypoglycemic coma", "Thyroid storm", "Myxedema coma"]'::jsonb, 3, 'Myxedema coma is severe decompensated hypothyroidism presenting with hypothermia, bradycardia, hypotension, hypoventilation, altered mental status, hyponatremia, and hypoglycemia, typically precipitated by medication nonadherence, infection, or cold exposure in an older patient with long-standing hypothyroidism. Thyroid storm is the opposite state, with hyperthermia, tachycardia, and agitation rather than hypothermia and bradycardia. Septic shock causes fever and tachycardia rather than hypothermia and bradycardia, although infection can precipitate myxedema coma. Adrenal crisis can cause hypotension and hypoglycemia but does not explain the hypothermia, bradycardia, and markedly elevated TSH with undetectable T4. Hypoglycemia alone does not explain the hypothermia, bradycardia, and thyroid laboratory pattern.', 'Medium', 39, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 78-year-old man with myxedema coma is admitted to the intensive care unit. He is hypothermic, bradycardic, hypotensive, and hypoventilating. Which of the following is the most appropriate initial management?', '["Radioactive iodine ablation", "High-dose methimazole", "Emergent thyroidectomy", "Oral levothyroxine alone and discharge home", "Intravenous levothyroxine, glucocorticoids, supportive care including rewarming and ventilatory support, and treatment of the precipitating cause"]'::jsonb, 3, 'Myxedema coma is a medical emergency treated in the intensive care unit with intravenous levothyroxine, stress-dose glucocorticoids given before or with thyroid hormone because of possible coexistent adrenal insufficiency, and supportive care including passive rewarming, ventilatory support, and correction of hyponatremia and hypoglycemia, along with identification and treatment of the precipitating cause. Oral levothyroxine alone is inadequate because of impaired gut absorption and the severity of illness. Radioactive iodine and methimazole are treatments for hyperthyroidism and would worsen hypothyroidism. Thyroidectomy has no role in myxedema coma and would be dangerous in an unstable patient.', 'Hard', 40, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 52-year-old asymptomatic woman is found on routine screening to have a TSH of 6.8 mIU/L with a normal free T4 of 1.1 ng/dL. She has positive anti-TPO antibodies and no symptoms of hypothyroidism. What is the most appropriate management?', '["Start full-dose levothyroxine immediately", "Start levothyroxine because TSH is above 5 mIU/L regardless of symptoms", "Monitor TSH periodically, and consider treatment if TSH rises above 10 mIU/L or symptoms develop", "Order radioactive iodine uptake scan", "Start methimazole"]'::jsonb, 2, 'This patient has subclinical hypothyroidism, defined as an elevated TSH with a normal free T4. Treatment is generally recommended when the TSH exceeds 10 mIU/L, or when symptoms are present, whereas a TSH between 5 and 10 mIU/L in an asymptomatic patient is usually monitored with periodic TSH checks. Starting full-dose levothyroxine for mild subclinical disease risks overtreatment and iatrogenic thyrotoxicosis. A radioactive iodine uptake scan is not indicated in hypothyroidism. Methimazole treats hyperthyroidism and would worsen this patient''s condition.', 'Medium', 41, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 68-year-old woman with atrial fibrillation is found to have a TSH of 0.08 mIU/L with a normal free T4 and normal total T3. She has no symptoms of hyperthyroidism and is not taking thyroid hormone. Which of the following is the most appropriate next step?', '["Start methimazole immediately", "Reassure and do nothing because subclinical hyperthyroidism never requires treatment", "Evaluate for causes, assess bone and cardiac risk, and consider treatment given her age and atrial fibrillation", "Perform total thyroidectomy", "Start levothyroxine"]'::jsonb, 2, 'Subclinical hyperthyroidism is a suppressed TSH with normal free T4 and T3. In a 68-year-old with atrial fibrillation, treatment is generally considered because subclinical hyperthyroidism increases the risk of atrial fibrillation, osteoporosis, and fractures in older adults, and guidelines recommend treating older patients and those with cardiac disease or low bone density. Starting methimazole immediately without evaluating the cause is premature, since the cause may be transient thyroiditis or exogenous thyroid hormone. Doing nothing ignores the established cardiac and bone risks in this age group. Thyroidectomy is not first-line for subclinical disease. Levothyroxine would worsen hyperthyroidism.', 'Medium', 42, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 36-year-old woman presents with 2 weeks of anterior neck pain radiating to the jaw, fever, and palpitations. Examination shows a tender, firm, enlarged thyroid gland. Laboratory studies show TSH 0.05 mIU/L, free T4 elevated, ESR 95 mm/hr, and low radioactive iodine uptake. She had a viral upper respiratory infection 3 weeks ago. What is the most likely diagnosis?', '["Graves disease", "Hashimoto thyroiditis", "Subacute (de Quervain) thyroiditis", "Acute suppurative thyroiditis", "Toxic multinodular goiter"]'::jsonb, 2, 'Subacute thyroiditis, or de Quervain thyroiditis, typically follows a viral illness and presents with a painful, tender thyroid, thyrotoxicosis from release of preformed hormone, a markedly elevated ESR, and low radioactive iodine uptake because the inflamed gland cannot take up iodine. Graves disease causes a painless goiter with high iodine uptake and positive TSI. Hashimoto thyroiditis causes hypothyroidism with a nontender goiter. Acute suppurative thyroiditis is bacterial, usually unilateral with an abscess, and is rare. Toxic multinodular goiter causes hyperthyroidism with a nodular gland and high or patchy uptake.', 'Medium', 43, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 30-year-old woman presents with 4 weeks of palpitations, tremor, and weight loss. She delivered a healthy baby 3 months ago. Examination shows a nontender, mildly enlarged thyroid gland. Laboratory studies show TSH 0.02 mIU/L, free T4 elevated, ESR 12 mm/hr, and low radioactive iodine uptake. Thyroid-stimulating immunoglobulin is negative. What is the most likely diagnosis?', '["Subacute thyroiditis", "Toxic adenoma", "Pituitary adenoma", "Graves disease", "Postpartum thyroiditis"]'::jsonb, 3, 'Postpartum thyroiditis is a painless, destructive thyroiditis occurring within the first year after delivery, presenting with a transient hyperthyroid phase followed by hypothyroidism, a nontender gland, normal ESR, low radioactive iodine uptake, and negative TSI. Graves disease would show positive TSI and high iodine uptake. Subacute thyroiditis causes a painful, tender thyroid with a markedly elevated ESR. A toxic adenoma causes a single hyperfunctioning nodule with suppression of the rest of the gland. A pituitary adenoma would show an elevated or inappropriately normal TSH.', 'Medium', 44, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 45-year-old man presents with palpitations and weight loss 6 weeks after a flu-like illness. Examination shows a nontender thyroid gland. Laboratory studies show suppressed TSH, elevated free T4, normal ESR, and low radioactive iodine uptake. Which of the following is the most appropriate management?', '["Methimazole for 18 months", "Radioactive iodine ablation", "Beta-blocker for symptom control and observation, as the condition is usually self-limited", "Total thyroidectomy", "High-dose glucocorticoids"]'::jsonb, 2, 'This presentation is consistent with silent (painless) thyroiditis, a destructive thyroiditis with a transient hyperthyroid phase that is usually self-limited. Management is symptomatic with a beta-blocker for palpitations and tremor, with observation and monitoring for the hypothyroid phase that often follows. Methimazole is ineffective because the hyperthyroidism results from release of preformed hormone rather than increased synthesis. Radioactive iodine is not indicated for a self-limited destructive process and uptake is low. Thyroidectomy is not appropriate. Glucocorticoids are reserved for severe subacute thyroiditis with pain, not silent thyroiditis.', 'Hard', 45, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 48-year-old woman is found to have a 2.5-cm solitary thyroid nodule on physical examination. She is euthyroid with a normal TSH. Neck ultrasound shows a solid, hypoechoic nodule with irregular margins and microcalcifications. What is the most appropriate next step in management?', '["Reassure and repeat examination in 1 year", "Start levothyroxine suppression therapy", "Fine-needle aspiration biopsy of the nodule", "Radioactive iodine ablation", "Total thyroidectomy without further testing"]'::jsonb, 2, 'Bethesda category III is an indeterminate result with a low but nonzero risk of malignancy, and the recommended approach is repeat fine-needle aspiration, often with molecular testing to refine risk, rather than immediate surgery. Immediate total thyroidectomy is overly aggressive for an indeterminate result with a low malignancy risk and exposes the patient to unnecessary surgical complications. Radioactive iodine is not used for an indeterminate nodule of unknown pathology. Methimazole treats hyperthyroidism and has no role in a euthyroid patient with an indeterminate nodule. Discharge without follow-up is inappropriate because the nodule requires further evaluation and surveillance.', 'Medium', 46, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 55-year-old man has a 1.2-cm thyroid nodule that is solid and hypoechoic on ultrasound with no suspicious features. His TSH is normal. Fine-needle aspiration is performed and the cytology is reported as Bethesda category III, atypia of undetermined significance. What is the most appropriate next step?', '["Repeat fine-needle aspiration in 3 months or consider molecular testing", "Immediate total thyroidectomy", "Radioactive iodine ablation", "Start methimazole", "Discharge without follow-up"]'::jsonb, 0, 'Papillary thyroid carcinoma is the most common thyroid cancer and is typically treated with thyroidectomy followed by radioactive iodine ablation to destroy residual thyroid tissue, then levothyroxine at a TSH-suppressive dose to prevent recurrence, with long-term monitoring of thyroglobulin. Chemotherapy is not used for differentiated thyroid cancer and has no role in papillary carcinoma. External beam radiation is reserved for unresectable or anaplastic disease. Observation alone after surgery is inadequate for a 3-cm papillary cancer because adjuvant radioactive iodine reduces recurrence. Methimazole treats hyperthyroidism and has no role in thyroid cancer management.', 'Hard', 47, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 33-year-old woman undergoes thyroidectomy for a 3-cm thyroid nodule. Pathology shows papillary thyroid carcinoma with psammoma bodies and Orphan Annie eye nuclei. There is no extrathyroidal extension or lymph node involvement. What is the most appropriate next step in management?', '["External beam radiation", "Observation without further treatment", "Methimazole therapy", "Chemotherapy", "Radioactive iodine ablation followed by TSH-suppressive levothyroxine therapy"]'::jsonb, 3, 'Follicular thyroid carcinoma spreads hematogenously, most commonly to bone and lung, in contrast to papillary thyroid carcinoma, which spreads primarily through lymphatics to cervical lymph nodes. Follicular carcinoma is diagnosed by capsular or vascular invasion on pathology and cannot be diagnosed by fine-needle aspiration alone, because the cytology resembles a benign follicular adenoma. Direct tracheal extension can occur with large tumors but is not the characteristic pattern of spread. Peritoneal spread and cerebrospinal fluid spread are not typical routes for follicular thyroid cancer.', 'Medium', 48, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 50-year-old man presents with a slowly growing thyroid mass and a history of a Hurthle cell neoplasm. After thyroidectomy, pathology shows follicular thyroid carcinoma with capsular invasion but no vascular invasion. Which of the following best describes the typical pattern of spread of follicular thyroid cancer?', '["Peritoneal spread", "Spread through the cerebrospinal fluid", "Lymphatic spread to cervical nodes first", "Hematogenous spread to bone and lung", "Direct extension into the trachea only"]'::jsonb, 4, 'Medullary thyroid cancer arises from parafollicular C cells, secretes calcitonin, and is associated with RET mutations in multiple endocrine neoplasia type 2. Management is total thyroidectomy with central neck dissection, and patients must be screened for pheochromocytoma before surgery and for hyperparathyroidism, because MEN 2A includes both conditions. Observation is inappropriate for a known RET mutation carrier with an elevated calcitonin, since the cancer will progress. Radioactive iodine is ineffective because C cells do not take up iodine. Methimazole and levothyroxine suppression have no role in medullary thyroid cancer.', 'Medium', 49, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 28-year-old woman presents with a thyroid nodule. Her mother died of medullary thyroid cancer. Laboratory studies show an elevated serum calcitonin. Genetic testing reveals a RET proto-oncogene mutation. Which of the following is the most appropriate management?', '["Methimazole therapy", "Levothyroxine suppression therapy", "Observation with annual ultrasound", "Total thyroidectomy with central neck dissection and screening for pheochromocytoma and hyperparathyroidism", "Radioactive iodine ablation"]'::jsonb, 4, 'Medullary thyroid cancer arises from parafollicular C cells, secretes calcitonin, and is associated with RET mutations in multiple endocrine neoplasia type 2. Management is total thyroidectomy with central neck dissection, and patients must be screened for pheochromocytoma before surgery and for hyperparathyroidism, because MEN 2A includes both. Observation is inappropriate for a known RET mutation carrier with an elevated calcitonin. Radioactive iodine is ineffective because C cells do not take up iodine. Methimazole and levothyroxine suppression have no role in medullary thyroid cancer.', 'Hard', 50, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 72-year-old man presents with a rapidly enlarging, hard, fixed neck mass over 3 weeks, hoarseness, dysphagia, and stridor. Fine-needle aspiration shows undifferentiated pleomorphic cells. Which of the following is the most likely diagnosis and its prognosis?', '["Medullary thyroid carcinoma with an intermediate prognosis", "Hashimoto thyroiditis with a benign course", "Papillary thyroid carcinoma with an excellent prognosis", "Anaplastic thyroid carcinoma with a very poor prognosis", "Follicular thyroid carcinoma with a good prognosis"]'::jsonb, 4, 'Sick euthyroid syndrome, or nonthyroidal illness syndrome, occurs in critically ill patients and is characterized by low total T3, elevated reverse T3, and a low-normal or mildly suppressed TSH with a normal free T4, reflecting impaired peripheral conversion of T4 to T3 during severe illness. Graves disease would show a suppressed TSH with elevated free T4 and clinical hyperthyroidism. Primary hypothyroidism would show an elevated TSH with low free T4, the opposite pattern. Central hypothyroidism would show a low free T4 with a low or inappropriately normal TSH, without the reverse T3 elevation. Thyroid hormone resistance causes elevated thyroid hormones with a nonsuppressed TSH.', 'Medium', 51, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 70-year-old man is admitted to the intensive care unit with severe pneumonia and sepsis. Laboratory studies show TSH 0.3 mIU/L, free T4 0.9 ng/dL, total T3 markedly low, and reverse T3 elevated. He has no history of thyroid disease and no goiter. What is the most likely explanation for these findings?', '["Graves disease", "Primary hypothyroidism", "Sick euthyroid syndrome (nonthyroidal illness)", "Central hypothyroidism", "Thyroid hormone resistance"]'::jsonb, 2, 'Sick euthyroid syndrome, or nonthyroidal illness syndrome, occurs in critically ill patients and is characterized by low total T3, elevated reverse T3, and a low-normal or mildly suppressed TSH with a normal free T4, reflecting impaired peripheral conversion of T4 to T3 during severe illness. Graves disease would show a suppressed TSH with elevated free T4. Primary hypothyroidism would show an elevated TSH with low free T4. Central hypothyroidism would show a low free T4 with a low or inappropriately normal TSH, without the reverse T3 elevation. Thyroid hormone resistance causes elevated thyroid hormones with a nonsuppressed TSH.', 'Medium', 52, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 65-year-old man with atrial fibrillation has been taking amiodarone for 2 years. He now reports fatigue, weight gain, and cold intolerance. Laboratory studies show TSH 22 mIU/L and free T4 0.5 ng/dL. Which of the following is the most likely cause of his hypothyroidism?', '["Amiodarone-induced hypothyroidism from iodine excess and the Wolff-Chaikoff effect", "Graves disease", "Subacute thyroiditis", "Iodine deficiency", "Pituitary adenoma"]'::jsonb, 0, 'Type 2 amiodarone-induced thyrotoxicosis is a destructive thyroiditis that occurs in a previously normal gland, with absent vascularity on ultrasound and elevated inflammatory markers such as interleukin-6, and it is treated with glucocorticoids. Type 1 occurs in patients with underlying thyroid disease such as Graves disease or nodular goiter, shows increased vascularity, and is treated with thionamides. Graves disease would show positive thyroid-stimulating immunoglobulin and increased vascularity on ultrasound. Subacute thyroiditis causes a painful, tender thyroid gland. Emergency thyroidectomy is not first-line for amiodarone-induced thyrotoxicosis and is reserved for refractory cases.', 'Medium', 53, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 58-year-old woman taking amiodarone for ventricular tachycardia develops palpitations, tremor, and weight loss. Laboratory studies show TSH <0.01 mIU/L and free T4 3.8 ng/dL. Thyroid ultrasound shows a normal-sized gland without increased vascularity, and interleukin-6 is elevated. Which type of amiodarone-induced thyrotoxicosis is most likely, and what is the most appropriate treatment?', '["Subacute thyroiditis; treat with NSAIDs only", "Thyroid storm; treat with emergency thyroidectomy", "Type 1 amiodarone-induced thyrotoxicosis; treat with methimazole", "Type 2 amiodarone-induced thyrotoxicosis; treat with glucocorticoids", "Graves disease; treat with radioactive iodine"]'::jsonb, 4, 'Type 2 amiodarone-induced thyrotoxicosis is a destructive thyroiditis that occurs in a previously normal gland, with absent vascularity on ultrasound and elevated inflammatory markers such as interleukin-6, and it is treated with glucocorticoids. Type 1 occurs in patients with underlying thyroid disease such as Graves disease or nodular goiter, shows increased vascularity, and is treated with thionamides. Graves disease would show positive TSI and increased vascularity. Subacute thyroiditis causes a painful thyroid. Emergency thyroidectomy is not first-line for amiodarone-induced thyrotoxicosis.', 'Hard', 54, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 30-year-old woman at 8 weeks gestation is diagnosed with Graves disease. She has palpitations, tremor, and a heart rate of 118/min. Which of the following is the most appropriate initial treatment?', '["Methimazole", "Propylthiouracil during the first trimester, then switch to methimazole", "Radioactive iodine ablation", "Total thyroidectomy immediately", "No treatment until after delivery"]'::jsonb, 1, 'Propylthiouracil is preferred in the first trimester of pregnancy because methimazole is associated with congenital anomalies such as aplasia cutis and choanal atresia, while propylthiouracil carries a risk of hepatotoxicity that makes it less desirable later in pregnancy, so patients are switched to methimazole after the first trimester. Methimazole in the first trimester is avoided because of teratogenicity. Radioactive iodine is contraindicated in pregnancy. Immediate thyroidectomy is not first-line and carries surgical risk in pregnancy. Leaving hyperthyroidism untreated in pregnancy risks miscarriage, preeclampsia, and fetal complications.', 'Hard', 55, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 32-year-old woman at 10 weeks gestation has a history of Hashimoto thyroiditis and takes levothyroxine 75 mcg daily. Her TSH is 5.2 mIU/L. What is the most appropriate management?', '["Continue the same dose and recheck TSH after delivery", "Increase levothyroxine dose by approximately 30% and recheck TSH in 4 weeks", "Stop levothyroxine because thyroid hormone is harmful in pregnancy", "Switch to methimazole", "Order radioactive iodine uptake scan"]'::jsonb, 1, 'Thyroid hormone requirements increase by approximately 30 percent in pregnancy, and the target TSH in the first trimester is below 2.5 mIU/L, so the levothyroxine dose should be increased and the TSH rechecked in 4 weeks to confirm the target is reached. Continuing the same dose leaves her undertreated, which increases the risk of miscarriage, preeclampsia, and impaired fetal neurodevelopment. Stopping levothyroxine would worsen hypothyroidism and harm the pregnancy. Methimazole treats hyperthyroidism and has no role in hypothyroidism. Radioactive iodine is contraindicated in pregnancy and is never used to evaluate hypothyroidism.', 'Medium', 56, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 60-year-old man presents with a 4-cm thyroid nodule that is hyperfunctioning on radioactive iodine uptake scan, with suppression of the surrounding thyroid tissue. His TSH is suppressed and free T4 is elevated. What is the most likely diagnosis?', '["Papillary thyroid carcinoma", "Toxic adenoma", "Hashimoto thyroiditis", "Subacute thyroiditis", "Medullary thyroid carcinoma"]'::jsonb, 1, 'A toxic adenoma is a single autonomously functioning thyroid nodule that produces excess thyroid hormone, suppresses TSH, and appears as a hot nodule with suppression of the surrounding gland on radioactive iodine uptake scan. Papillary thyroid carcinoma typically appears as a cold nodule and does not cause hyperthyroidism. Hashimoto thyroiditis causes hypothyroidism with a diffusely enlarged gland, not a single hot nodule. Subacute thyroiditis shows low uptake throughout the gland and causes a painful thyroid. Medullary thyroid carcinoma arises from C cells, secretes calcitonin, and does not cause hyperthyroidism or appear as a hot nodule.', 'Easy', 57, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 45-year-old woman with Graves disease is scheduled for radioactive iodine ablation. She is not pregnant and has no eye disease. Which of the following counseling points is most important before the procedure?', '["She will need to take methimazole for life after the procedure", "She should avoid pregnancy for at least 6 months after treatment and expect possible hypothyroidism requiring lifelong levothyroxine", "Radioactive iodine is safe during breastfeeding", "She can stop all follow-up after the procedure", "Radioactive iodine never causes hypothyroidism"]'::jsonb, 1, 'Radioactive iodine ablation commonly leads to hypothyroidism requiring lifelong levothyroxine replacement, and pregnancy must be avoided for at least 6 months after treatment because of radiation exposure to the ovaries and the risk to a future pregnancy. Methimazole is stopped before radioactive iodine and is not continued for life after ablation. Radioactive iodine is contraindicated during breastfeeding and should not be given to a lactating woman. Lifelong follow-up with thyroid function monitoring is essential after ablation. Hypothyroidism is the expected outcome of successful ablation, not a rare complication, and patients must be counseled about it.', 'Medium', 58, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 50-year-old man with untreated Graves disease presents with fever, confusion, and tachycardia. His Burch-Wartofsky score is 50. In addition to beta-blockers, cooling, and fluids, he is given propylthiouracil. One hour later, which medication should be given next?', '["Levothyroxine", "Potassium iodide (inorganic iodine)", "Methimazole", "Radioactive iodine", "Lithium"]'::jsonb, 1, 'In thyroid storm, inorganic iodine such as potassium iodide or Lugol solution is given at least 1 hour after the thionamide to block the release of preformed thyroid hormone from the gland. Giving iodine before the thionamide would provide substrate for new hormone synthesis and worsen thyrotoxicosis, so the order of administration matters. Levothyroxine would worsen hyperthyroidism and has no role in thyroid storm. Adding methimazole on top of propylthiouracil is unnecessary and does not block hormone release. Radioactive iodine is too slow for the acute setting and is contraindicated in thyroid storm.', 'Hard', 59, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 62-year-old woman with a history of Hashimoto thyroiditis presents with progressive dysphagia and a rapidly enlarging, hard thyroid mass over 6 weeks. Fine-needle aspiration shows large atypical lymphoid cells. Which of the following is the most likely diagnosis?', '["Papillary thyroid carcinoma", "Primary thyroid lymphoma", "Anaplastic thyroid carcinoma", "Follicular thyroid carcinoma", "Medullary thyroid carcinoma"]'::jsonb, 1, 'Primary thyroid lymphoma, most commonly diffuse large B-cell lymphoma, occurs almost exclusively in patients with Hashimoto thyroiditis and presents with a rapidly enlarging thyroid mass causing compressive symptoms, with large atypical lymphoid cells on cytology. Papillary carcinoma grows slowly and shows Orphan Annie eye nuclei and psammoma bodies, not large lymphoid cells. Anaplastic carcinoma shows undifferentiated pleomorphic cells and occurs in older patients with a rapidly growing mass, but the cytology here shows lymphoid cells. Follicular carcinoma is diagnosed by capsular or vascular invasion. Medullary carcinoma arises from C cells and secretes calcitonin.', 'Hard', 60, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 48-year-old woman presents with 18 months of progressive central weight gain, a round face, purple abdominal striae, easy bruising, hypertension, and new hyperglycemia. Laboratory testing shows an elevated 24-hour urine free cortisol and an elevated plasma ACTH. A high-dose dexamethasone suppression test suppresses cortisol by more than 50%. What is the most appropriate next step in management?', '["CT of the abdomen with adrenal protocol", "MRI of the pituitary gland", "Bilateral inferior petrosal sinus sampling", "Plasma free metanephrines", "Repeat 24-hour urine free cortisol"]'::jsonb, 1, 'In Cushing disease, ACTH-dependent hypercortisolism that suppresses on high-dose dexamethasone points to a pituitary source, so MRI of the pituitary is the next step to localize the adenoma before transsphenoidal surgery. Adrenal CT is used when ACTH is suppressed, indicating an adrenal source, which is not the case here. Bilateral inferior petrosal sinus sampling is reserved for cases where MRI is negative or equivocal, not as the first test. Plasma metanephrines evaluate pheochromocytoma, which does not explain hypercortisolism. Repeating the 24-hour urine cortisol adds nothing because hypercortisolism is already established and the source now needs localization.', 'Medium', 61, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 62-year-old man with small cell lung cancer presents with severe muscle weakness, hypokalemia, metabolic alkalosis, hyperpigmentation, and new hyperglycemia. Plasma ACTH is markedly elevated and cortisol does not suppress with high-dose dexamethasone. What is the most likely cause of his hypercortisolism?', '["Pituitary corticotroph adenoma", "Adrenal cortical adenoma", "Ectopic CRH secretion from a carcinoid tumor", "Ectopic ACTH secretion from small cell lung cancer", "Primary hyperaldosteronism"]'::jsonb, 3, 'Ectopic ACTH secretion, classically from small cell lung cancer, causes ACTH-dependent hypercortisolism with very high ACTH levels, hypokalemic metabolic alkalosis, and failure to suppress with high-dose dexamethasone, because the tumor secretes ACTH autonomously. A pituitary adenoma in Cushing disease usually suppresses with high-dose dexamethasone and has more modest ACTH elevation. An adrenal adenoma causes ACTH-independent disease with suppressed ACTH. Ectopic CRH is rare and would still be ACTH-driven but is far less common than ectopic ACTH in this setting. Primary hyperaldosteronism causes hypertension and hypokalemia but not hypercortisolism, hyperpigmentation, or hyperglycemia.', 'Hard', 62, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 34-year-old woman presents with weight gain, hirsutism, amenorrhea, hypertension, and easy bruising. A 1-mg overnight dexamethasone suppression test fails to suppress cortisol, and plasma ACTH is undetectable. What is the most appropriate initial test to localize the source?', '["CT of the abdomen with adrenal protocol", "MRI of the pituitary gland", "Bilateral inferior petrosal sinus sampling", "Midnight salivary cortisol", "CRH stimulation test"]'::jsonb, 0, 'Suppressed ACTH with confirmed hypercortisolism indicates ACTH-independent Cushing syndrome from an adrenal source, most commonly a cortisol-secreting adrenal adenoma, so CT of the abdomen with adrenal protocol is the appropriate localizing test. Pituitary MRI is used for ACTH-dependent disease, which is excluded by the undetectable ACTH. Bilateral inferior petrosal sinus sampling distinguishes pituitary from ectopic ACTH sources and has no role when ACTH is suppressed. Midnight salivary cortisol is a screening test for hypercortisolism, not a localizing study. The CRH stimulation test helps distinguish pituitary from ectopic ACTH excess and is not useful in ACTH-independent disease.', 'Medium', 63, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 38-year-old woman presents with 6 months of fatigue, weight loss, nausea, and darkening of her skin, especially over her knuckles and gums. Her blood pressure is 92/60 mm Hg. Laboratory testing shows sodium 128 mEq/L, potassium 5.8 mEq/L, glucose 62 mg/dL, morning cortisol 4 mcg/dL, and markedly elevated ACTH. Antibodies to 21-hydroxylase are positive. What is the most appropriate long-term treatment?', '["Hydrocortisone alone", "Prednisone alone", "Hydrocortisone plus fludrocortisone", "Dexamethasone alone", "Intravenous normal saline alone"]'::jsonb, 2, 'This is primary adrenal insufficiency (Addison disease), confirmed by low cortisol with elevated ACTH and positive 21-hydroxylase antibodies, which destroys both glucocorticoid and mineralocorticoid production. Long-term treatment therefore requires both hydrocortisone for glucocorticoid replacement and fludrocortisone for mineralocorticoid replacement. Hydrocortisone or prednisone alone would leave aldosterone deficiency untreated, causing persistent hyponatremia, hyperkalemia, and hypotension. Dexamethasone alone also lacks mineralocorticoid activity and is not used for chronic replacement. Intravenous saline treats acute hypotension but does not replace deficient hormones and is not a long-term therapy.', 'Medium', 64, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 60-year-old man with rheumatoid arthritis has taken prednisone 15 mg daily for 3 years. He abruptly stops the medication and 2 days later presents with severe nausea, vomiting, abdominal pain, confusion, and hypotension with a blood pressure of 78/50 mm Hg. His glucose is 58 mg/dL and sodium is 126 mEq/L. What is the most appropriate immediate management?', '["Restart oral prednisone at the previous dose", "Fludrocortisone alone", "Intravenous dexamethasone alone", "Cosyntropin stimulation test before any treatment", "Intravenous hydrocortisone and normal saline"]'::jsonb, 4, 'Abrupt cessation of chronic glucocorticoids causes secondary adrenal insufficiency and adrenal crisis, a life-threatening emergency presenting with hypotension, hypoglycemia, hyponatremia, and altered mental status. Immediate treatment is stress-dose intravenous hydrocortisone plus aggressive intravenous normal saline, without waiting for diagnostic testing. Restarting oral prednisone is too slow and unreliable in a vomiting, hypotensive patient. Fludrocortisone alone does not replace glucocorticoids, and mineralocorticoid deficiency is not the main problem in secondary insufficiency. Dexamethasone alone is not preferred because it does not allow a cosyntropin test afterward, though hydrocortisone is standard. Diagnostic testing must never delay treatment in suspected adrenal crisis.', 'Medium', 65, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 52-year-old woman who underwent transsphenoidal resection of a pituitary macroadenoma 2 years ago presents with fatigue, weight loss, dizziness on standing, and nausea. Morning cortisol is 3 mcg/dL and ACTH is low. A cosyntropin stimulation test shows a blunted cortisol rise. What is the most likely diagnosis?', '["Primary adrenal insufficiency", "Secondary adrenal insufficiency from hypopituitarism", "Cushing syndrome", "Primary hyperaldosteronism", "Pheochromocytoma"]'::jsonb, 1, 'Low cortisol with low ACTH after pituitary surgery indicates secondary adrenal insufficiency from hypopituitarism, because the pituitary can no longer secrete ACTH to stimulate the adrenal glands. The blunted cosyntropin response reflects adrenal atrophy from chronic lack of ACTH stimulation. Primary adrenal insufficiency would show elevated ACTH, not low ACTH. Cushing syndrome causes cortisol excess, the opposite of this presentation. Primary hyperaldosteronism causes hypertension and hypokalemia without cortisol deficiency. Pheochromocytoma causes episodic hypertension, headache, and palpitations, not fatigue, hypotension, and low cortisol.', 'Medium', 66, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 52-year-old woman has blood pressure of 168/102 mm Hg despite amlodipine, lisinopril, and hydrochlorothiazide. Laboratory testing shows potassium 3.1 mEq/L, bicarbonate 30 mEq/L, and an aldosterone-to-renin ratio of 45 (normal <30). What is the most appropriate confirmatory test for the suspected diagnosis?', '["Saline suppression test", "CT of the adrenal glands", "Plasma free metanephrines", "Renal artery duplex ultrasound", "Overnight dexamethasone suppression test"]'::jsonb, 0, 'Resistant hypertension with hypokalemia, metabolic alkalosis, and an elevated aldosterone-to-renin ratio suggests primary hyperaldosteronism, and the diagnosis is confirmed with a saline suppression test, which demonstrates failure of aldosterone to suppress after volume expansion. Adrenal CT is performed after biochemical confirmation to distinguish adenoma from hyperplasia, not as the confirmatory test. Plasma metanephrines evaluate pheochromocytoma, which is not suggested here. Renal artery duplex evaluates renovascular hypertension, which typically causes hypokalemia through secondary hyperaldosteronism but with elevated renin. The dexamethasone suppression test screens for Cushing syndrome, which is not the leading diagnosis.', 'Hard', 67, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 48-year-old man has resistant hypertension and hypokalemia. Biochemical testing confirms primary hyperaldosteronism. CT shows a 1.8-cm left adrenal adenoma, and adrenal vein sampling lateralizes aldosterone production to the left adrenal gland. What is the most appropriate treatment?', '["Lifelong spironolactone", "Bilateral adrenalectomy", "Amiloride", "Unilateral laparoscopic adrenalectomy", "Thiazide diuretic"]'::jsonb, 3, 'Unilateral aldosterone-producing adenoma confirmed by adrenal vein sampling is treated with unilateral laparoscopic adrenalectomy, which can cure hypertension and hypokalemia. Lifelong spironolactone is the treatment for bilateral adrenal hyperplasia, not for a lateralized adenoma. Bilateral adrenalectomy would cause permanent adrenal insufficiency and is never performed for this indication. Amiloride blocks the epithelial sodium channel and can help with hypokalemia but does not remove the source of excess aldosterone. A thiazide diuretic would worsen hypokalemia and does not treat the underlying aldosterone excess.', 'Medium', 68, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 55-year-old woman has resistant hypertension and hypokalemia with an elevated aldosterone-to-renin ratio. Confirmatory testing confirms primary hyperaldosteronism. Adrenal vein sampling shows no lateralization, consistent with bilateral adrenal hyperplasia. What is the most appropriate management?', '["Unilateral adrenalectomy", "Hydrochlorothiazide", "Spironolactone", "ACE inhibitor alone", "Amlodipine"]'::jsonb, 2, 'Bilateral adrenal hyperplasia causing primary hyperaldosteronism is treated medically with a mineralocorticoid receptor antagonist such as spironolactone, which blocks aldosterone at its receptor and controls both blood pressure and hypokalemia. Unilateral adrenalectomy is only useful when aldosterone production lateralizes to one gland. Hydrochlorothiazide would worsen hypokalemia and does not address aldosterone excess. An ACE inhibitor alone is insufficient because aldosterone production in primary hyperaldosteronism is independent of angiotensin II. Amlodipine lowers blood pressure but does not correct the hypokalemia or the underlying mineralocorticoid excess.', 'Medium', 69, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 40-year-old man presents with episodic severe headaches, palpitations, and sweating accompanied by blood pressure spikes to 210/120 mm Hg. Between episodes his blood pressure is normal. Plasma free metanephrines are markedly elevated. What is the most appropriate next step in management?', '["Start a beta-blocker immediately", "CT of the abdomen with adrenal protocol", "MIBG scan as the first imaging study", "24-hour urine free cortisol", "Adrenal vein sampling"]'::jsonb, 1, 'Markedly elevated plasma free metanephrines in a patient with paroxysmal hypertension, headache, palpitations, and diaphoresis establish the diagnosis of pheochromocytoma, and CT of the abdomen is the next step to localize the tumor, since most pheochromocytomas are adrenal. Starting a beta-blocker first is dangerous because unopposed alpha stimulation can precipitate hypertensive crisis; alpha-blockade must come first. MIBG scanning is reserved for cases where CT is negative or metastatic disease is suspected. Urine free cortisol evaluates Cushing syndrome, which does not explain these episodes. Adrenal vein sampling is used for hyperaldosteronism, not pheochromocytoma.', 'Medium', 70, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 46-year-old woman with a confirmed pheochromocytoma is scheduled for laparoscopic adrenalectomy. She is currently hypertensive with a blood pressure of 172/104 mm Hg and a heart rate of 108 beats per minute. What is the most important preoperative step?', '["Beta-blocker first, then surgery", "No preoperative medication is needed", "Metyrosine alone", "Intravenous fluids only", "Alpha-blockade with phenoxybenzamine for 10 to 14 days, then a beta-blocker"]'::jsonb, 4, 'Before resection of a pheochromocytoma, alpha-adrenergic blockade with phenoxybenzamine for 10 to 14 days is essential to prevent intraoperative hypertensive crisis from catecholamine release during tumor manipulation. A beta-blocker is added only after adequate alpha-blockade, because beta-blockade alone leaves alpha-mediated vasoconstriction unopposed and can precipitate a crisis. Operating without preoperative preparation risks severe hypertension, arrhythmia, and death. Metyrosine, which inhibits catecholamine synthesis, is reserved for patients who cannot tolerate alpha-blockade or have metastatic disease. Intravenous fluids help expand the contracted intravascular volume but do not prevent catecholamine-induced vasoconstriction.', 'Hard', 71, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 35-year-old woman presents with paroxysmal hypertension, headaches, and palpitations. Plasma free metanephrines are markedly elevated, but CT of the abdomen shows normal adrenal glands. Her father had a pheochromocytoma. What is the best next imaging study?', '["123I-MIBG scan or DOTATATE PET/CT", "Adrenal vein sampling", "Repeat plasma free metanephrines", "MRI of the pituitary gland", "Renal angiography"]'::jsonb, 0, 'When plasma metanephrines are elevated but adrenal imaging is normal, an extra-adrenal paraganglioma should be suspected, and functional imaging with 123I-MIBG or DOTATATE PET/CT is the best next step to locate the tumor anywhere in the body. Adrenal vein sampling is used to lateralize aldosterone production in primary hyperaldosteronism and has no role in pheochromocytoma. Repeating plasma metanephrines is unnecessary because the biochemical diagnosis is already established. Pituitary MRI is irrelevant to catecholamine excess. Renal angiography evaluates renovascular hypertension and would not locate a paraganglioma.', 'Hard', 72, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 2-week-old infant with ambiguous genitalia presents with vomiting, poor feeding, and lethargy. Laboratory testing shows sodium 124 mEq/L, potassium 6.4 mEq/L, glucose 48 mg/dL, and 17-hydroxyprogesterone markedly elevated. Karyotype is 46,XX. What is the most appropriate immediate treatment?', '["Immediate genital surgery", "Dexamethasone alone", "Oral hydrocortisone alone", "Intravenous hydrocortisone, normal saline, and fludrocortisone", "Spironolactone"]'::jsonb, 3, 'This newborn has classic salt-wasting 21-hydroxylase deficiency: ambiguous genitalia in a genetic female, hyponatremia, hyperkalemia, hypoglycemia, and markedly elevated 17-hydroxyprogesterone. The immediate priority is stress-dose intravenous hydrocortisone with normal saline and fludrocortisone to correct the adrenal crisis and mineralocorticoid deficiency. Surgery is deferred until the infant is stable and the diagnosis is confirmed. Dexamethasone alone does not provide mineralocorticoid replacement. Oral hydrocortisone alone is inadequate in a critically ill, vomiting newborn. Spironolactone is a mineralocorticoid antagonist and would worsen salt wasting.', 'Medium', 73, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'An 8-year-old girl presents with early pubic hair, clitoromegaly, and accelerated growth. Bone age is advanced by 3 years. Laboratory testing shows markedly elevated 17-hydroxyprogesterone with normal sodium and potassium. What is the most appropriate long-term treatment?', '["Fludrocortisone alone", "GnRH agonist alone", "Hydrocortisone replacement", "Bilateral adrenalectomy", "Spironolactone"]'::jsonb, 2, 'Simple virilizing 21-hydroxylase deficiency causes androgen excess with normal mineralocorticoid production, presenting with early pubarche, clitoromegaly, and advanced bone age without salt wasting. Long-term treatment is glucocorticoid replacement with hydrocortisone, which suppresses ACTH-driven androgen production and prevents further virilization. Fludrocortisone is only needed when aldosterone production is deficient, which it is not here. A GnRH agonist does not address the adrenal androgen excess. Bilateral adrenalectomy is not indicated and would create permanent adrenal insufficiency. Spironolactone is an antiandrogen but does not suppress adrenal androgen production and is not the standard treatment.', 'Medium', 74, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 3-week-old boy presents with vomiting, poor feeding, and lethargy. Laboratory testing shows sodium 122 mEq/L, potassium 6.8 mEq/L, glucose 45 mg/dL, and 17-hydroxyprogesterone markedly elevated. His genitalia are normal. What is the most important next step?', '["Wait for genetic testing before treating", "Intravenous hydrocortisone and normal saline", "Oral salt tablets only", "Fludrocortisone alone", "Discharge with close outpatient follow-up"]'::jsonb, 1, 'Salt-wasting congenital adrenal hyperplasia in a male infant presents with vomiting, poor feeding, hyponatremia, hyperkalemia, and elevated 17-hydroxyprogesterone, and it can rapidly progress to fatal adrenal crisis. The most important immediate step is stress-dose intravenous hydrocortisone with intravenous normal saline to replace glucocorticoids and restore intravascular volume. Waiting for genetic testing delays life-saving treatment. Oral salt tablets alone do not replace cortisol. Fludrocortisone alone does not treat glucocorticoid deficiency. Discharging the infant would risk death from adrenal crisis and dehydration.', 'Medium', 75, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 52-year-old man presents with enlarged hands and feet, jaw protrusion, increased shoe size, headaches, and loss of peripheral vision. Examination shows bitemporal hemianopsia. Serum IGF-1 is markedly elevated. What is the most appropriate next step?', '["Oral glucose suppression test", "CT of the adrenal glands", "Serum prolactin", "Thyroid ultrasound", "MRI of the pituitary gland"]'::jsonb, 4, 'Acromegaly from a growth hormone-secreting pituitary adenoma presents with enlarged hands and feet, jaw protrusion, headaches, and bitemporal hemianopsia from optic chiasm compression, with elevated IGF-1 confirming the diagnosis. MRI of the pituitary is the next step to localize the adenoma and assess its size and relationship to the optic chiasm before surgery. An oral glucose suppression test is a confirmatory test for growth hormone excess but does not localize the tumor. Adrenal CT is irrelevant to growth hormone excess. Serum prolactin may be mildly elevated from stalk effect but is not the key test. Thyroid ultrasound does not evaluate pituitary disease.', 'Medium', 76, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 50-year-old woman has confirmed acromegaly with a 1.2-cm pituitary macroadenoma on MRI and no visual field defect. Her IGF-1 is markedly elevated. What is the most appropriate first-line treatment?', '["Transsphenoidal surgical resection", "Octreotide as first-line therapy", "Radiation therapy as first-line therapy", "Dopamine agonist therapy", "Observation without treatment"]'::jsonb, 0, 'Transsphenoidal surgical resection is the first-line treatment for acromegaly caused by a growth hormone-secreting pituitary adenoma, offering the best chance of cure, especially for microadenomas and resectable macroadenomas. Somatostatin analogs such as octreotide are used when surgery is unsuccessful, contraindicated, or as adjunctive therapy, not as first-line treatment. Radiation is reserved for persistent disease after surgery and medical therapy because its effect is slow. Dopamine agonists are less effective for growth hormone excess and are not first-line. Observation is inappropriate because untreated acromegaly causes progressive cardiovascular, metabolic, and musculoskeletal complications.', 'Medium', 77, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 48-year-old man underwent transsphenoidal resection of a growth hormone-secreting pituitary adenoma 6 months ago. His IGF-1 remains elevated and MRI shows a small residual tumor. He has no visual field defect. What is the most appropriate next step in management?', '["Immediate repeat surgery", "Radiation therapy alone", "Bromocriptine", "Octreotide, a somatostatin analog", "Pegvisomant as first-line medical therapy"]'::jsonb, 3, 'After incomplete surgical resection of a growth hormone-secreting adenoma with persistently elevated IGF-1, a somatostatin analog such as octreotide is the preferred medical therapy because it suppresses growth hormone secretion and can shrink residual tumor. Immediate repeat surgery is not the standard next step when medical therapy is available and effective. Radiation is reserved for disease refractory to medical therapy because its benefit takes years. Bromocriptine is a dopamine agonist with limited efficacy in acromegaly and is not first-line medical therapy. Pegvisomant, a growth hormone receptor antagonist, is used when somatostatin analogs fail, not as the initial medical option.', 'Hard', 78, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 28-year-old woman presents with 8 months of amenorrhea and galactorrhea. Serum prolactin is 180 ng/mL (normal <25 ng/mL), thyroid function is normal, and MRI shows a 7-mm pituitary microadenoma. What is the most appropriate first-line treatment?', '["Transsphenoidal surgery", "Cabergoline", "Oral contraceptives alone", "Radiation therapy", "Observation without treatment"]'::jsonb, 1, 'A prolactinoma is the most common functioning pituitary adenoma, and dopamine agonists such as cabergoline are first-line treatment because they suppress prolactin secretion and shrink the tumor in most patients. Transsphenoidal surgery is reserved for dopamine agonist resistance, intolerance, or pituitary apoplexy. Oral contraceptives restore menses but do not treat the tumor or the hyperprolactinemia. Radiation is rarely used and is reserved for refractory cases. Observation is inappropriate because the tumor may grow and the patient has symptomatic hyperprolactinemia with amenorrhea and galactorrhea.', 'Medium', 79, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 45-year-old man presents with decreased libido, erectile dysfunction, and headaches. Serum prolactin is 95 ng/mL, testosterone is low, and MRI shows a 1.8-cm pituitary macroadenoma compressing the optic chiasm with a bitemporal hemianopsia. What is the most appropriate initial management?', '["Immediate transsphenoidal surgery", "Testosterone replacement first", "Radiation therapy", "Observation without treatment", "Cabergoline"]'::jsonb, 4, 'Dopamine agonists such as cabergoline are first-line treatment even for macroprolactinomas, including those causing visual field defects, because they shrink the tumor in most patients and often restore vision without surgery. Immediate surgery is reserved for pituitary apoplexy, rapid visual deterioration, or dopamine agonist failure. Testosterone replacement treats hypogonadism but does not address the tumor or the hyperprolactinemia. Radiation is rarely used for prolactinomas and is reserved for refractory disease. Observation is inappropriate because the macroadenoma is compressing the optic chiasm and causing progressive symptoms.', 'Hard', 80, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 30-year-old woman with schizophrenia treated with risperidone presents with galactorrhea and amenorrhea for 4 months. Serum prolactin is 60 ng/mL, thyroid function is normal, and MRI of the pituitary is normal. What is the most appropriate next step?', '["Start cabergoline immediately", "Repeat the prolactin level in 3 months", "Switch risperidone to a prolactin-sparing antipsychotic", "Transsphenoidal surgery", "Levothyroxine replacement"]'::jsonb, 2, 'Risperidone is a dopamine antagonist that commonly causes hyperprolactinemia, and with a normal MRI the most likely cause is drug-induced rather than a pituitary adenoma. The appropriate step is to switch to a prolactin-sparing antipsychotic such as aripiprazole in consultation with psychiatry, which usually normalizes prolactin and resolves galactorrhea. Starting cabergoline treats the prolactin level but does not address the causative drug and may worsen psychosis. Repeating the prolactin level is reasonable but does not solve the problem, since the drug is the clear cause. Transsphenoidal surgery is inappropriate without a tumor. Thyroid replacement is irrelevant because thyroid function is normal.', 'Medium', 81, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 50-year-old woman presents with fatigue, cold intolerance, and amenorrhea. Five years ago she had a severe postpartum hemorrhage and never produced breast milk. Laboratory testing shows low cortisol, low free T4 with low TSH, and low FSH and LH. What is the most appropriate initial treatment?', '["Hydrocortisone first, then levothyroxine", "Levothyroxine first, then hydrocortisone", "Estrogen replacement alone", "Growth hormone replacement first", "Desmopressin"]'::jsonb, 0, 'Sheehan syndrome is postpartum pituitary necrosis from severe hemorrhage, causing panhypopituitarism with failure to lactate, amenorrhea, and deficiency of ACTH, TSH, and gonadotropins. Glucocorticoid replacement must be given before thyroid hormone, because levothyroxine increases cortisol clearance and can precipitate adrenal crisis in a cortisol-deficient patient. Giving levothyroxine first is therefore dangerous. Estrogen alone does not address the life-threatening cortisol deficiency. Growth hormone replacement is not urgent and is considered only after other axes are replaced. Desmopressin treats diabetes insipidus, which is uncommon in Sheehan syndrome because the posterior pituitary usually survives.', 'Hard', 82, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 60-year-old man presents with headaches and progressive loss of peripheral vision. Examination shows bitemporal hemianopsia. Laboratory testing shows low testosterone, low free T4 with low TSH, and a mildly elevated prolactin of 45 ng/mL. MRI shows a 2.2-cm pituitary macroadenoma. What is the most appropriate treatment?', '["Cabergoline", "Octreotide", "Radiation therapy as first-line treatment", "Transsphenoidal surgical resection", "Observation without treatment"]'::jsonb, 3, 'A nonfunctioning pituitary macroadenoma causing mass effect with bitemporal hemianopsia and hypopituitarism is treated with transsphenoidal surgical resection to decompress the optic chiasm and preserve vision. Cabergoline is effective only for prolactinomas, and this tumor does not secrete prolactin beyond a mild stalk effect. Octreotide is used for growth hormone-secreting adenomas, not nonfunctioning tumors. Radiation is reserved for residual or recurrent disease after surgery because its effect is slow and it can worsen hypopituitarism. Observation is inappropriate because the tumor is already compressing the optic chiasm and causing progressive visual loss.', 'Medium', 83, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 55-year-old man with a known pituitary macroadenoma presents with sudden severe headache, vomiting, visual loss, and hypotension. His blood pressure is 82/54 mm Hg and he has a bitemporal hemianopsia. What is the most appropriate immediate management?', '["Oral prednisone", "Lumbar puncture", "Dopamine agonist therapy", "Observation", "Intravenous hydrocortisone and urgent neurosurgical evaluation"]'::jsonb, 4, 'Pituitary apoplexy is acute hemorrhage or infarction of a pituitary adenoma, presenting with sudden severe headache, vomiting, visual loss, and hypotension from acute cortisol deficiency. Immediate management is stress-dose intravenous hydrocortisone to treat adrenal insufficiency, together with urgent neurosurgical evaluation for decompression of the optic chiasm. Oral prednisone is inadequate and unreliable in a vomiting, hypotensive patient. A dopamine agonist has no role in apoplexy and does not treat the hemorrhage. Observation is dangerous because vision can be permanently lost and adrenal crisis can be fatal. Lumbar puncture is contraindicated with a sellar mass and would not change management.', 'Hard', 84, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 10-year-old boy presents with poor growth, headaches, and loss of peripheral vision. Examination shows bitemporal hemianopsia. CT of the head shows a calcified suprasellar mass. What is the most likely diagnosis?', '["Pituitary adenoma", "Meningioma", "Craniopharyngioma", "Germinoma", "Rathke cleft cyst"]'::jsonb, 2, 'Craniopharyngioma is a benign suprasellar tumor that typically presents in children with growth failure, headaches, and bitemporal hemianopsia, and a calcified suprasellar mass on imaging is characteristic. A pituitary adenoma is uncommon in children and is rarely calcified. A meningioma can occur in the suprasellar region but does not typically cause growth failure in a child. A germinoma is a suprasellar tumor but usually presents with diabetes insipidus and does not show the classic calcifications of craniopharyngioma. A Rathke cleft cyst is a benign cystic lesion that is usually asymptomatic and does not cause growth failure or calcified masses.', 'Medium', 85, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 50-year-old woman with chronic headaches undergoes MRI of the brain, which shows cerebrospinal fluid filling the sella turcica with a flattened pituitary gland. Pituitary hormone levels are normal and visual fields are full. What is the most appropriate management?', '["Transsphenoidal surgery", "Cabergoline", "Hydrocortisone replacement", "Radiation therapy", "Reassurance and observation"]'::jsonb, 4, 'Empty sella syndrome occurs when cerebrospinal fluid herniates into the sella turcica, flattening the pituitary gland, and it is often an incidental finding in patients with normal pituitary function. When pituitary hormone levels are normal and there is no visual field defect, the appropriate management is reassurance and observation without surgery or medication. Surgery is reserved for cerebrospinal fluid leak or progressive visual loss. Cabergoline treats prolactinomas, which are not present here. Hydrocortisone is given only when cortisol deficiency is documented. Radiation is not indicated for a benign, nonfunctioning finding.', 'Medium', 86, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 30-year-old man presents with excessive thirst, frequent urination, and headaches. Laboratory testing shows hypernatremia with dilute urine consistent with central diabetes insipidus. MRI shows a suprasellar mass with a thickened pituitary stalk, and cerebrospinal fluid beta-hCG is elevated. What is the most likely diagnosis?', '["Germinoma", "Craniopharyngioma", "Prolactinoma", "Meningioma", "Lymphocytic hypophysitis"]'::jsonb, 0, 'A suprasellar mass with diabetes insipidus, a thickened pituitary stalk, and elevated beta-hCG in cerebrospinal fluid is most consistent with a germinoma, a germ cell tumor that commonly arises in the suprasellar region in young patients. Craniopharyngioma typically presents with growth failure and calcified masses and does not secrete beta-hCG. A prolactinoma causes hyperprolactinemia with galactorrhea and amenorrhea, not diabetes insipidus with elevated hCG. A meningioma is a dural-based tumor that does not secrete beta-hCG. Lymphocytic hypophysitis causes pituitary enlargement and hypopituitarism but does not elevate cerebrospinal fluid beta-hCG.', 'Hard', 87, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 40-year-old man has hypercalcemia from parathyroid hyperplasia, a prolactinoma, and a pancreatic gastrinoma causing Zollinger-Ellison syndrome with severe peptic ulcer disease. Which gene is most likely mutated in this patient?', '["RET proto-oncogene", "VHL gene", "NF1 gene", "MEN1 gene", "SDHB gene"]'::jsonb, 3, 'The combination of primary hyperparathyroidism, a prolactinoma, and a gastrinoma causing Zollinger-Ellison syndrome is classic for multiple endocrine neoplasia type 1, caused by a mutation in the MEN1 gene encoding menin. The RET proto-oncogene causes MEN types 2A and 2B, which feature medullary thyroid cancer and pheochromocytoma, not parathyroid hyperplasia with gastrinoma. The VHL gene causes von Hippel-Lindau syndrome with hemangioblastomas and renal cell carcinoma. The NF1 gene causes neurofibromatosis type 1 with cafe-au-lait spots and neurofibromas. SDHB mutations cause hereditary paraganglioma and pheochromocytoma syndromes, not this triad.', 'Medium', 88, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 35-year-old woman has medullary thyroid cancer, a pheochromocytoma, and primary hyperparathyroidism. Her 10-year-old daughter is healthy. What is the most appropriate screening test for the daughter?', '["MEN1 genetic testing", "RET genetic testing", "VHL genetic testing", "Serum calcium only", "No screening is needed"]'::jsonb, 1, 'Medullary thyroid cancer, pheochromocytoma, and primary hyperparathyroidism define MEN type 2A, caused by an activating mutation in the RET proto-oncogene. First-degree relatives should be screened with RET genetic testing so that carriers can undergo prophylactic thyroidectomy before medullary thyroid cancer develops. MEN1 testing is for the MEN1 syndrome with parathyroid, pituitary, and pancreatic tumors. VHL testing is for von Hippel-Lindau syndrome, which does not include medullary thyroid cancer. Checking calcium alone would miss the genetic risk and does not screen for medullary thyroid cancer. No screening is inappropriate because MEN 2A is autosomal dominant with high penetrance.', 'Medium', 89, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 25-year-old man presents with medullary thyroid cancer, a pheochromocytoma, mucosal neuromas on his lips and tongue, and a marfanoid body habitus. What is the most appropriate management?', '["Thyroid lobectomy", "Parathyroidectomy first", "Total thyroidectomy after excluding pheochromocytoma", "Observation without treatment", "Radioactive iodine therapy"]'::jsonb, 2, 'Medullary thyroid cancer with pheochromocytoma, mucosal neuromas, and a marfanoid habitus defines MEN type 2B, caused by a RET mutation. The treatment for medullary thyroid cancer is total thyroidectomy, but pheochromocytoma must be excluded or treated first, because anesthesia and surgery can trigger a life-threatening catecholamine crisis. Thyroid lobectomy is inadequate because medullary thyroid cancer is often bilateral and multifocal. Parathyroidectomy is not the priority, since hyperparathyroidism is uncommon in MEN 2B. Observation is inappropriate because medullary thyroid cancer in MEN 2B is aggressive and occurs early. Radioactive iodine is ineffective because medullary thyroid cancer does not take up iodine.', 'Hard', 90, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 58-year-old woman presents with recurrent calcium kidney stones, fatigue, and bone pain. Serum calcium is 11.2 mg/dL, parathyroid hormone (PTH) is markedly elevated, phosphate is low, and 25-hydroxyvitamin D is normal. Dual-energy x-ray absorptiometry (DEXA) shows osteoporosis at the hip. Which of the following is the most appropriate next step in management?', '["Observation with annual calcium monitoring", "Parathyroidectomy", "Cinacalcet therapy", "Thiazide diuretic therapy", "Bisphosphonate therapy alone"]'::jsonb, 1, 'This patient has symptomatic primary hyperparathyroidism with hypercalcemia, nephrolithiasis, and osteoporosis, all of which are indications for parathyroidectomy, the only curative treatment. Surgery removes the adenoma and normalizes calcium, improves bone density, and prevents further stones. Observation is reserved for asymptomatic patients who meet none of the surgical criteria. Cinacalcet lowers calcium but does not improve bone density or cure the disease and is used mainly when surgery is not possible. Thiazide diuretics reduce urinary calcium but do not treat the underlying adenoma. Bisphosphonates improve bone density but do not address the hypercalcemia or stone risk.', 'Medium', 91, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 62-year-old woman is found to have a serum calcium of 10.6 mg/dL and an elevated PTH level on routine labs. She has no kidney stones, no fractures, and no symptoms. DEXA shows a T-score of -1.2, estimated glomerular filtration rate is 78 mL/min, and 24-hour urinary calcium is normal. Which of the following is the most appropriate management?', '["Parathyroidectomy", "Cinacalcet therapy", "Bisphosphonate therapy", "Surveillance with annual calcium, creatinine, and bone density monitoring", "Thiazide diuretic therapy"]'::jsonb, 3, 'This patient has asymptomatic primary hyperparathyroidism and meets none of the surgical criteria, which include serum calcium more than 1 mg/dL above normal, kidney stones or nephrocalcinosis, eGFR below 60, osteoporosis with T-score -2.5 or lower, or age under 50. In such patients, surveillance with annual calcium and creatinine, periodic bone density testing, and adequate hydration and vitamin D repletion is appropriate. Parathyroidectomy is indicated only when criteria are met or symptoms develop. Cinacalcet is used when surgery is contraindicated, not as first-line therapy in asymptomatic disease. Bisphosphonates are not indicated without osteoporosis. Thiazides are not a treatment for primary hyperparathyroidism.', 'Medium', 92, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 34-year-old man presents with hypercalcemia, elevated PTH, and a history of recurrent kidney stones. His father had hyperparathyroidism and a pituitary tumor, and his sister has Zollinger-Ellison syndrome. Imaging shows multigland parathyroid enlargement. Which of the following is the most likely diagnosis?', '["Multiple endocrine neoplasia type 1", "Familial hypocalciuric hypercalcemia", "Lithium-induced hyperparathyroidism", "Humoral hypercalcemia of malignancy", "Vitamin D intoxication"]'::jsonb, 0, 'Multiple endocrine neoplasia type 1 (MEN1) is an autosomal dominant syndrome caused by a menin gene mutation and classically involves the parathyroids, pituitary, and pancreas, the three Ps. Primary hyperparathyroidism in MEN1 typically involves multigland hyperplasia rather than a single adenoma and presents at a younger age with a strong family history. Familial hypocalciuric hypercalcemia causes mild hypercalcemia with low urinary calcium and inappropriately normal PTH, not multigland disease. Lithium can cause hyperparathyroidism but does not explain the pituitary and pancreatic tumors. Humoral hypercalcemia of malignancy is PTH-independent with suppressed PTH. Vitamin D intoxication causes hypercalcemia with suppressed PTH.', 'Hard', 93, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 46-year-old woman is 24 hours post total thyroidectomy for papillary thyroid cancer. She reports perioral numbness, tingling in her hands, and muscle cramps. Examination shows a positive Chvostek sign. Serum calcium is 7.0 mg/dL, phosphate is 5.8 mg/dL, and PTH is undetectable. Which of the following is the most appropriate immediate treatment?', '["Oral calcitriol", "Intravenous magnesium sulfate", "Intravenous calcium gluconate", "Recombinant PTH infusion", "Furosemide"]'::jsonb, 2, 'This patient has acute symptomatic hypocalcemia from postoperative hypoparathyroidism after thyroidectomy, with perioral numbness, tetany, and a positive Chvostek sign. Intravenous calcium gluconate is the immediate treatment for symptomatic hypocalcemia, as it rapidly raises ionized calcium and relieves neuromuscular symptoms. Oral calcitriol is used for long-term maintenance but acts too slowly for acute symptoms. Magnesium should be checked and replaced if deficient, but it is not the primary acute therapy. Recombinant PTH is not used in the acute postoperative setting. Furosemide increases urinary calcium loss and would worsen hypocalcemia.', 'Medium', 94, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 12-year-old boy presents with short stature, a round face, obesity, and shortening of the fourth and fifth metacarpals. Labs show calcium 7.2 mg/dL, phosphate 6.1 mg/dL, and PTH markedly elevated. Which of the following is the most likely diagnosis?', '["Hypoparathyroidism", "Vitamin D deficiency", "Chronic kidney disease", "Primary hyperparathyroidism", "Pseudohypoparathyroidism"]'::jsonb, 4, 'Pseudohypoparathyroidism is characterized by end-organ resistance to PTH, so PTH is elevated yet calcium is low and phosphate is high, mimicking hypoparathyroidism biochemically. The Albright hereditary osteodystrophy phenotype of short stature, round face, obesity, and shortened fourth and fifth metacarpals is classic. True hypoparathyroidism has low PTH, not elevated PTH. Vitamin D deficiency causes low calcium with high PTH but lacks the skeletal phenotype and usually has low or normal phosphate. Chronic kidney disease causes a similar biochemical pattern but does not cause Albright features. Primary hyperparathyroidism causes hypercalcemia, the opposite of this presentation.', 'Hard', 95, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 68-year-old man with metastatic squamous cell lung cancer presents with confusion, nausea, and polyuria. Serum calcium is 13.5 mg/dL, PTH is suppressed, and PTH-related peptide is elevated. Which of the following is the most appropriate initial treatment?', '["Furosemide", "Intravenous normal saline", "Calcitonin alone", "Hemodialysis", "Oral phosphate"]'::jsonb, 1, 'This patient has humoral hypercalcemia of malignancy mediated by PTH-related peptide, a common cause of hypercalcemia in squamous cell lung cancer. The first step in management is aggressive intravenous normal saline hydration, which restores intravascular volume and increases urinary calcium excretion. Furosemide should only be given after volume repletion, as giving it first worsens dehydration and hypercalcemia. Calcitonin works quickly but its effect is transient and it is an adjunct, not initial therapy. Hemodialysis is reserved for severe refractory hypercalcemia or renal failure. Oral phosphate is not used due to the risk of ectopic calcification.', 'Medium', 96, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 52-year-old woman with sarcoidosis presents with fatigue and constipation. Serum calcium is 12.0 mg/dL, PTH is suppressed, PTH-related peptide is normal, and 1,25-dihydroxyvitamin D is markedly elevated. Chest imaging shows bilateral hilar lymphadenopathy. Which of the following is the most appropriate treatment for her hypercalcemia?', '["Glucocorticoids", "Bisphosphonate", "Cinacalcet", "Calcitonin", "Intravenous saline alone"]'::jsonb, 0, 'In sarcoidosis, activated macrophages in granulomas convert 25-hydroxyvitamin D to 1,25-dihydroxyvitamin D, causing increased intestinal calcium absorption and hypercalcemia with suppressed PTH. Glucocorticoids are the treatment of choice because they inhibit the extrarenal 1-alpha-hydroxylase activity in macrophages and reduce calcitriol production. Bisphosphonates reduce bone resorption but do not address the excess calcitriol driving this form of hypercalcemia. Cinacalcet acts on the calcium-sensing receptor and is used in parathyroid disease, not granulomatous hypercalcemia. Calcitonin has only a brief effect. Saline hydration is supportive but does not correct the underlying mechanism.', 'Hard', 97, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 28-year-old man has a serum calcium of 10.8 mg/dL found incidentally. PTH is mildly elevated, 24-hour urinary calcium is very low, and the calcium-to-creatinine clearance ratio is 0.005. His father and brother have similar mild hypercalcemia without symptoms or stones. Which of the following is the most appropriate management?', '["Parathyroidectomy", "Cinacalcet therapy", "Thiazide diuretic therapy", "Reassurance with no surgery and periodic monitoring", "Bisphosphonate therapy"]'::jsonb, 3, 'This patient has familial hypocalciuric hypercalcemia, an autosomal dominant disorder caused by an inactivating mutation of the calcium-sensing receptor. It is characterized by mild asymptomatic hypercalcemia, inappropriately normal or mildly elevated PTH, and very low urinary calcium excretion with a calcium-to-creatinine clearance ratio below 0.01. The condition is benign and does not cause stones or bone disease, so parathyroidectomy is not indicated and is ineffective because the defect is in calcium sensing, not in a parathyroid adenoma. Cinacalcet and thiazides are not needed. Bisphosphonates have no role. Reassurance with periodic monitoring is the correct approach.', 'Hard', 98, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 50-year-old woman with chronic hypoparathyroidism after thyroidectomy is maintained on oral calcium carbonate and calcitriol. Her serum calcium is 8.6 mg/dL and she feels well. Which of the following is the most important long-term monitoring test in this patient?', '["Serum PTH level", "Bone mineral density", "24-hour urinary calcium", "Serum 25-hydroxyvitamin D level only", "Serum magnesium level"]'::jsonb, 2, 'In chronic hypoparathyroidism treated with calcium and calcitriol, the absence of PTH impairs renal calcium reabsorption, so these patients are at high risk of hypercalciuria, nephrolithiasis, and nephrocalcinosis even when serum calcium is normal. Monitoring 24-hour urinary calcium is essential to keep excretion in a safe range, adjusting the calcitriol dose or adding a thiazide diuretic if needed. Serum PTH remains low and is not useful for monitoring. Bone density is not the primary concern. Vitamin D levels should be maintained but do not detect hypercalciuria. Magnesium should be checked periodically but is not the most important long-term test.', 'Hard', 99, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 60-year-old man with a history of alcohol use presents with muscle cramps, paresthesias, and a prolonged QT interval on ECG. Serum calcium is 7.4 mg/dL, magnesium is 1.1 mg/dL, and PTH is elevated. Intravenous calcium gluconate provides only transient improvement. Which of the following is the most appropriate next step?', '["Intravenous calcium gluconate infusion", "Oral calcitriol", "Furosemide", "Oral vitamin D", "Intravenous magnesium sulfate"]'::jsonb, 4, 'Hypomagnesemia causes hypocalcemia that is refractory to calcium replacement because magnesium is required for PTH secretion and for PTH action at target tissues. This patient has low magnesium from chronic alcohol use, and his hypocalcemia will not correct until magnesium is repleted. Intravenous magnesium sulfate is therefore the key treatment. Additional calcium gluconate will only transiently raise calcium without fixing the underlying defect. Calcitriol and vitamin D do not address magnesium deficiency. Furosemide increases urinary magnesium and calcium losses and would worsen both deficiencies.', 'Medium', 100, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 68-year-old postmenopausal woman presents after a low-trauma wrist fracture. DEXA shows a T-score of -2.8 at the lumbar spine. She has no history of esophageal disease and normal renal function. Which of the following is the most appropriate initial treatment?', '["Calcium and vitamin D supplementation alone", "Alendronate", "Raloxifene", "Teriparatide", "Denosumab"]'::jsonb, 1, 'This patient has postmenopausal osteoporosis with a T-score of -2.8 and a prior fragility fracture, which is an indication for antiresorptive therapy. Alendronate, an oral bisphosphonate, is first-line treatment and reduces the risk of vertebral and hip fractures. Calcium and vitamin D alone are necessary adjuncts but insufficient in established osteoporosis with a fracture. Raloxifene reduces vertebral fractures but not hip fractures and increases thromboembolism risk. Teriparatide is reserved for severe osteoporosis with multiple fractures or treatment failure. Denosumab is effective but is usually considered when bisphosphonates are contraindicated or not tolerated.', 'Medium', 101, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 58-year-old postmenopausal woman with rheumatoid arthritis has taken prednisone 10 mg daily for the past year. DEXA shows a T-score of -1.8 at the hip. Which of the following is the most appropriate next step to prevent fractures?', '["Observation with annual DEXA", "Calcium and vitamin D supplementation alone", "Raloxifene", "Bisphosphonate therapy", "Teriparatide"]'::jsonb, 3, 'Glucocorticoids are the most common cause of secondary osteoporosis, causing rapid bone loss through increased resorption and decreased formation. Guidelines recommend bisphosphonate therapy for patients starting or continuing glucocorticoids at doses of 7.5 mg prednisone equivalent or higher for 3 months or more, particularly in postmenopausal women and older men. Observation is inappropriate given the high fracture risk. Calcium and vitamin D alone are insufficient. Raloxifene is not indicated for glucocorticoid-induced bone loss. Teriparatide is reserved for severe cases or bisphosphonate failure, not as initial therapy here.', 'Medium', 102, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 74-year-old woman with severe osteoporosis has a T-score of -3.5 and has sustained two new vertebral compression fractures despite 5 years of alendronate therapy. Which of the following is the most appropriate next treatment?', '["Teriparatide", "Continue alendronate", "Raloxifene", "Denosumab", "Calcitonin"]'::jsonb, 0, 'Teriparatide is a recombinant parathyroid hormone analog with anabolic effects on bone, stimulating new bone formation rather than simply reducing resorption. It is indicated for severe osteoporosis, defined by very low T-scores or fractures occurring despite antiresorptive therapy, as in this patient with a T-score of -3.5 and new vertebral fractures on alendronate. Continuing alendronate is inadequate since she has fractured while on it. Raloxifene reduces only vertebral fractures and is less potent. Denosumab is antiresorptive and does not build new bone. Calcitonin is weakly effective and is not recommended for severe osteoporosis.', 'Hard', 103, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 72-year-old woman who rarely goes outdoors presents with diffuse bone pain and proximal muscle weakness. Labs show calcium 8.0 mg/dL, phosphate 2.4 mg/dL, 25-hydroxyvitamin D 8 ng/mL, PTH elevated, and alkaline phosphatase elevated. X-ray shows a pseudofracture in the femoral neck. Which of the following is the most appropriate treatment?', '["Bisphosphonate therapy", "Calcium supplementation alone", "Vitamin D replacement with cholecalciferol", "Calcitriol alone", "Parathyroidectomy"]'::jsonb, 2, 'This patient has osteomalacia from vitamin D deficiency, characterized by bone pain, proximal muscle weakness, low calcium and 25-hydroxyvitamin D, elevated PTH, and elevated alkaline phosphatase from increased bone turnover. Vitamin D replacement corrects the deficiency, normalizes mineralization, and improves symptoms. Bisphosphonates are contraindicated in osteomalacia because they further impair mineralization of unmineralized osteoid. Calcium alone does not correct the vitamin D deficiency driving the disease. Calcitriol can be used in some settings but cholecalciferol repletion is the standard treatment for nutritional deficiency. Parathyroidectomy is not indicated because the PTH elevation is secondary to vitamin D deficiency.', 'Medium', 104, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 65-year-old woman presents with chronic bone pain and difficulty climbing stairs. Labs show low 25-hydroxyvitamin D, low-normal calcium, elevated PTH, and elevated alkaline phosphatase. Radiographs show Looser zones in the pubic rami. Which of the following is the most likely diagnosis?', '["Osteoporosis", "Paget disease of bone", "Multiple myeloma", "Primary hyperparathyroidism", "Osteomalacia"]'::jsonb, 4, 'Osteomalacia is a defect in bone mineralization caused by vitamin D deficiency, presenting with bone pain, muscle weakness, elevated alkaline phosphatase, and Looser zones or pseudofractures on imaging. Osteoporosis is a loss of bone mass with normal mineralization and typically has normal alkaline phosphatase. Paget disease causes markedly elevated alkaline phosphatase but with normal calcium and phosphate and characteristic radiographic changes. Multiple myeloma causes lytic lesions and hypercalcemia, not this biochemical pattern. Primary hyperparathyroidism causes hypercalcemia, which is absent here.', 'Medium', 105, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 70-year-old man presents with progressive hearing loss, an enlarged skull, and headaches. Labs show alkaline phosphatase 480 U/L with normal calcium and phosphate. Skull radiograph shows thickened calvarium with a cotton-wool appearance. Which of the following is the most appropriate treatment?', '["Observation with periodic alkaline phosphatase monitoring", "Zoledronic acid infusion", "Calcitonin as first-line therapy", "Vitamin D supplementation alone", "Denosumab"]'::jsonb, 1, 'Paget disease of bone is a disorder of disordered bone remodeling with markedly elevated alkaline phosphatase, normal calcium and phosphate, and characteristic radiographic findings. Skull involvement can cause hearing loss from compression of the eighth cranial nerve. Bisphosphonates, particularly a single infusion of zoledronic acid, are first-line treatment for symptomatic Paget disease and normalize alkaline phosphatase. Observation is appropriate only for asymptomatic patients with mildly elevated alkaline phosphatase. Calcitonin is second-line and less effective. Vitamin D alone does not treat Paget disease. Denosumab is not first-line therapy for Paget disease.', 'Medium', 106, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 66-year-old man is found to have an alkaline phosphatase of 180 U/L on routine labs. He has no bone pain, no deformity, and no fractures. Radiographs show mild Paget disease of the pelvis. Calcium and phosphate are normal. Which of the following is the most appropriate management?', '["Bisphosphonate therapy", "Calcitonin", "Denosumab", "Observation with periodic monitoring", "High-dose vitamin D"]'::jsonb, 3, 'Asymptomatic Paget disease with only mildly elevated alkaline phosphatase and no pain, deformity, fracture, or neurologic complication does not require treatment. Observation with periodic alkaline phosphatase monitoring and imaging is appropriate, with treatment reserved for symptomatic disease, marked alkaline phosphatase elevation, or involvement of weight-bearing bones or the skull. Bisphosphonates are indicated for symptomatic Paget disease, not for incidental asymptomatic findings. Calcitonin is second-line therapy for symptomatic disease. Denosumab is not standard treatment for Paget disease. Vitamin D supplementation alone does not treat the disordered bone remodeling.', 'Easy', 107, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 55-year-old man reports fatigue, low libido, and erectile dysfunction for one year. Two morning total testosterone levels are 180 and 195 ng/dL. LH is 18 IU/L and FSH is 22 IU/L. Prostate examination is normal and PSA is 1.2 ng/mL. Which of the following is the most appropriate treatment?', '["Testosterone replacement therapy", "Clomiphene citrate", "Human chorionic gonadotropin", "Anastrozole", "Observation"]'::jsonb, 0, 'This patient has primary hypogonadism, indicated by low testosterone with elevated LH and FSH, consistent with testicular failure. Testosterone replacement therapy is appropriate to improve libido, energy, muscle mass, and bone density. Before starting therapy, prostate cancer must be excluded with a digital rectal examination and PSA, and hematocrit should be monitored. Clomiphene and human chorionic gonadotropin are used for secondary hypogonadism when fertility is desired, not for primary testicular failure. Anastrozole is not a treatment for hypogonadism. Observation is inappropriate given his symptomatic low testosterone.', 'Medium', 108, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 40-year-old man presents with low libido, erectile dysfunction, and galactorrhea. Total testosterone is 150 ng/dL, LH is 1.2 IU/L, FSH is 1.5 IU/L, and prolactin is 120 ng/mL. Which of the following is the most appropriate next step?', '["Testosterone replacement therapy", "Clomiphene citrate", "Pituitary MRI and cabergoline", "Human chorionic gonadotropin", "Observation"]'::jsonb, 2, 'This patient has secondary hypogonadism from hyperprolactinemia, most likely a prolactinoma, which suppresses gonadotropin-releasing hormone and lowers LH, FSH, and testosterone. A pituitary MRI should be obtained to confirm the adenoma, and a dopamine agonist such as cabergoline is the treatment of choice, shrinking the tumor and restoring gonadal function. Testosterone replacement alone would not address the prolactinoma and could mask the diagnosis. Clomiphene is used in secondary hypogonadism without a prolactinoma. Human chorionic gonadotropin stimulates testosterone but does not treat the tumor. Observation is inappropriate with a likely pituitary adenoma.', 'Hard', 109, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 26-year-old woman presents with irregular periods, acne, and hirsutism. She has a body mass index of 32 kg/m2. Labs show elevated free testosterone and insulin resistance. Pelvic ultrasound shows multiple small ovarian follicles. She is not seeking pregnancy. Which of the following is the most appropriate initial management?', '["Metformin alone", "Combined oral contraceptive plus lifestyle modification", "Spironolactone alone", "Clomiphene citrate", "Weight loss alone"]'::jsonb, 1, 'This patient meets the Rotterdam criteria for polycystic ovary syndrome with irregular menses, clinical hyperandrogenism, and polycystic ovaries on ultrasound. For a woman not seeking pregnancy, first-line management is lifestyle modification plus a combined oral contraceptive, which regulates menses, reduces androgen levels, and treats acne and hirsutism. Metformin alone is less effective for menstrual regulation and hyperandrogenism. Spironolactone alone does not regulate menses. Clomiphene is used for ovulation induction when pregnancy is desired. Weight loss alone is helpful but insufficient as sole therapy for her symptoms.', 'Medium', 110, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 29-year-old woman with polycystic ovary syndrome has been unable to conceive after 12 months of trying. She has irregular menses and a body mass index of 30 kg/m2. Which of the following is the most appropriate first-line treatment for ovulation induction?', '["Combined oral contraceptive", "Metformin alone", "Clomiphene citrate", "Letrozole", "Spironolactone"]'::jsonb, 3, 'Letrozole, an aromatase inhibitor, is now first-line therapy for ovulation induction in women with polycystic ovary syndrome who desire pregnancy, with higher ovulation and live birth rates than clomiphene in randomized trials. Combined oral contraceptives suppress ovulation and are contraindicated when pregnancy is desired. Metformin alone has lower ovulation rates than letrozole and is used mainly as an adjunct in women with insulin resistance. Clomiphene was previously first-line but is less effective than letrozole. Spironolactone is teratogenic and is not used for ovulation induction.', 'Medium', 111, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 32-year-old woman with polycystic ovary syndrome, obesity, and a family history of type 2 diabetes asks about screening for diabetes. Which of the following is the recommended screening test?', '["Fasting plasma glucose alone", "HbA1c alone", "Lipid panel only", "No screening is needed", "75-gram oral glucose tolerance test"]'::jsonb, 4, 'Women with polycystic ovary syndrome have a markedly increased risk of insulin resistance, impaired glucose tolerance, and type 2 diabetes, and guidelines recommend screening with a 75-gram oral glucose tolerance test, which is more sensitive than fasting glucose or HbA1c in this population. Fasting glucose alone can miss impaired glucose tolerance because many women have normal fasting values despite postprandial hyperglycemia. HbA1c is less sensitive for early dysglycemia in PCOS. Lipid screening is important but does not assess glucose tolerance. No screening would miss a high-risk, treatable condition.', 'Medium', 112, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 19-year-old woman presents with primary amenorrhea. She has normal breast development and pubic hair. Pelvic examination reveals a blind-ending vagina, and ultrasound shows an absent uterus with normal ovaries. Karyotype is 46,XX. Which of the following is the most likely diagnosis?', '["Mullerian agenesis (Mayer-Rokitansky-Kuster-Hauser syndrome)", "Turner syndrome", "Androgen insensitivity syndrome", "Kallmann syndrome", "Polycystic ovary syndrome"]'::jsonb, 0, 'This patient has primary amenorrhea with normal breast development, indicating normal estrogen production, but an absent uterus and a blind-ending vagina, which is classic for Mayer-Rokitansky-Kuster-Hauser syndrome, or Mullerian agenesis, caused by failure of Mullerian duct development. Turner syndrome causes primary amenorrhea with short stature and absent breast development due to gonadal dysgenesis. Androgen insensitivity syndrome presents with a blind vagina but also with absent pubic hair and a female phenotype with testes, and breast development occurs. Kallmann syndrome causes delayed puberty with absent breast development and anosmia. PCOS causes secondary amenorrhea, not primary amenorrhea with an absent uterus.', 'Hard', 113, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 22-year-old competitive runner with a body mass index of 17 kg/m2 has had no periods for 8 months. She has no galactorrhea, no hirsutism, and no history of uterine instrumentation. Labs show estradiol low, FSH 3 IU/L, LH 2 IU/L, prolactin normal, and thyroid-stimulating hormone normal. Which of the following is the most likely diagnosis?', '["Polycystic ovary syndrome", "Premature ovarian insufficiency", "Functional hypothalamic amenorrhea", "Asherman syndrome", "Prolactinoma"]'::jsonb, 2, 'Functional hypothalamic amenorrhea is caused by energy deficiency, excessive exercise, or psychological stress, which suppresses gonadotropin-releasing hormone pulsatility and leads to low estrogen with low or normal FSH and LH. The diagnosis is supported by low body mass index, intensive exercise, and low estrogen without another cause. PCOS typically has normal or high LH and hyperandrogenism. Premature ovarian insufficiency causes high FSH with low estrogen. Asherman syndrome causes amenorrhea with normal hormone levels after uterine instrumentation. Prolactinoma causes amenorrhea with elevated prolactin and often galactorrhea.', 'Medium', 114, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 38-year-old woman presents with hirsutism that developed rapidly over 6 months, along with deepening of her voice and clitoromegaly. Total testosterone is 420 ng/dL and dehydroepiandrosterone sulfate is normal. Which of the following is the most appropriate next step?', '["Combined oral contraceptive plus spironolactone", "Pelvic and adrenal imaging to evaluate for an androgen-secreting tumor", "Metformin", "Dexamethasone", "Observation"]'::jsonb, 1, 'Rapid onset of hirsutism with virilization, including deepening voice, clitoromegaly, and markedly elevated testosterone, is concerning for an androgen-secreting tumor of the ovary or adrenal gland, which requires prompt imaging. Benign causes of hirsutism such as PCOS develop gradually over years with modest androgen elevation. Starting an oral contraceptive and spironolactone without excluding a tumor would delay diagnosis of a potentially malignant lesion. Metformin treats insulin resistance in PCOS but not a tumor. Dexamethasone is used for congenital adrenal hyperplasia, which does not present with rapid virilization in adulthood. Observation is inappropriate with these red flags.', 'Hard', 115, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 24-year-old woman with polycystic ovary syndrome has gradually worsening hirsutism over 2 years. Testosterone is mildly elevated and she is not seeking pregnancy. Which of the following is the most appropriate treatment?', '["Spironolactone alone", "Metformin alone", "Finasteride", "Combined oral contraceptive plus spironolactone", "Surgical evaluation"]'::jsonb, 3, 'For gradual hirsutism due to PCOS in a woman not seeking pregnancy, first-line therapy is a combined oral contraceptive, which suppresses ovarian androgen production and increases sex hormone-binding globulin, combined with spironolactone, an androgen receptor antagonist that directly blocks androgen effects on hair follicles. Spironolactone alone is less effective and should be combined with contraception due to teratogenicity. Metformin improves insulin resistance but has modest effects on hirsutism. Finasteride is not first-line. Surgery is indicated only for an androgen-secreting tumor, not for gradual PCOS-related hirsutism.', 'Medium', 116, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 48-year-old man with a body mass index of 42 kg/m2, type 2 diabetes, and hypertension has failed 12 months of lifestyle modification and pharmacologic weight loss therapy. His diabetes remains uncontrolled on metformin. Which of the following is the most appropriate next step?', '["Referral for bariatric surgery", "Orlistat", "Long-term phentermine", "Continue lifestyle modification alone", "GLP-1 receptor agonist alone"]'::jsonb, 0, 'Bariatric surgery is indicated for patients with a body mass index of 40 kg/m2 or higher, or 35 kg/m2 or higher with obesity-related comorbidities such as type 2 diabetes, after failure of lifestyle and pharmacologic therapy. This patient has a BMI of 42 with diabetes and hypertension that are uncontrolled despite medical management, making surgical referral appropriate. Orlistat and phentermine have modest efficacy and are not sufficient for this degree of obesity with comorbidities. Continuing lifestyle measures alone has already failed. A GLP-1 receptor agonist is reasonable but less effective than surgery for sustained weight loss and diabetes remission in class III obesity.', 'Medium', 117, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 52-year-old woman with a body mass index of 36 kg/m2 and type 2 diabetes on metformin has an HbA1c of 8.2%. She wishes to lose weight and improve her diabetes control. Which of the following is the most appropriate medication to add?', '["Orlistat", "Phentermine-topiramate", "Semaglutide", "Metformin alone", "Bariatric surgery"]'::jsonb, 2, 'GLP-1 receptor agonists such as semaglutide produce substantial weight loss and improve glycemic control in patients with obesity and type 2 diabetes, making them an excellent choice for this patient. Orlistat has modest weight loss efficacy and significant gastrointestinal side effects. Phentermine-topiramate is effective but is not preferred when diabetes control is a major goal and it has more contraindications. Metformin alone provides minimal weight loss. Bariatric surgery is not indicated at this BMI without additional comorbidities or failure of medical therapy.', 'Medium', 118, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 58-year-old man presents with episodic facial flushing, chronic diarrhea, and wheezing. Examination reveals a right-sided heart murmur, and echocardiography shows tricuspid regurgitation. Urinary 5-HIAA is markedly elevated. Which of the following is the most appropriate treatment for his symptoms?', '["Chemotherapy", "Beta-blocker therapy", "Antihistamine therapy", "Surgical resection alone", "Octreotide"]'::jsonb, 4, 'Carcinoid syndrome is caused by serotonin and other vasoactive substances secreted by a metastatic neuroendocrine tumor, typically of the small bowel, presenting with flushing, diarrhea, bronchospasm, and right-sided valvular heart disease from serotonin-induced fibrosis. Elevated urinary 5-HIAA confirms the diagnosis. Octreotide, a somatostatin analog, is first-line therapy and controls flushing and diarrhea by inhibiting hormone secretion. Chemotherapy has limited efficacy in well-differentiated carcinoid tumors. Beta-blockers can worsen bronchospasm. Antihistamines do not control serotonin-mediated symptoms. Surgery is curative only for localized disease, not for metastatic disease with carcinoid syndrome.', 'Medium', 119, 'MCQ'),
('35f40902-2212-4757-ba84-40f81d6ce036', 'A 44-year-old woman presents with recurrent episodes of confusion, sweating, and tremor that occur in the morning before breakfast and resolve after eating. During an episode, glucose is 38 mg/dL, insulin is elevated, C-peptide is elevated, and beta-hydroxybutyrate is low. Which of the following is the most appropriate next step?', '["Diazoxide alone", "Octreotide therapy", "Observation with frequent glucose monitoring", "Whipple procedure", "Pancreatic imaging followed by surgical resection"]'::jsonb, 4, 'This patient has Whipple triad with fasting hypoglycemia, neuroglycopenic symptoms, and relief with glucose, along with inappropriately elevated insulin and C-peptide during hypoglycemia and suppressed ketones, which is diagnostic of endogenous hyperinsulinism from an insulinoma. The next step is localization of the tumor with pancreatic imaging such as contrast-enhanced CT or endoscopic ultrasound, followed by surgical resection, which is curative. Diazoxide can control hypoglycemia preoperatively but is not definitive therapy. Octreotide is not first-line for insulinoma. Observation alone is unsafe given recurrent severe hypoglycemia. A Whipple procedure is a major pancreatic resection that is not the standard operation for a small localized insulinoma.', 'Hard', 120, 'MCQ');
